        protected override void OnSourceInitialized(EventArgs e)
        {
            base.OnSourceInitialized(e);
            InitUsbDeviceChangePnpHook();
        }

        private void InitUsbDeviceChangePnpHook()
        {
            try
            {
                if (PresentationSource.FromVisual(this) is HwndSource source)
                {
                    source.AddHook(HwndDeviceChangeHook);
                    AppendAutoHubLog("[+] ⚡ SMART USB SNIFFER: Win32 PnP Hardware Hook (WM_DEVICECHANGE) Active [<10ms Detection].");
                }
            }
            catch { }
        }

        private IntPtr HwndDeviceChangeHook(IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled)
        {
            const int WM_DEVICECHANGE = 0x0219;
            const int DBT_DEVICEARRIVAL = 0x8000;
            const int DBT_DEVICEREMOVECOMPLETE = 0x8004;
            const int DBT_DEVNODES_CHANGED = 0x0007;

            if (msg == WM_DEVICECHANGE)
            {
                int wp = wParam.ToInt32();
                if (wp == DBT_DEVICEARRIVAL || wp == DBT_DEVICEREMOVECOMPLETE || wp == DBT_DEVNODES_CHANGED)
                {
                    _ = Dispatcher.InvokeAsync(async () =>
                    {
                        await TriggerInstantPnpDeviceProbeAsync(wp == DBT_DEVICEARRIVAL);
                    });
                }
            }
            return IntPtr.Zero;
        }

        private async Task TriggerInstantPnpDeviceProbeAsync(bool isArrival)
        {
            if (_isRadarBusy || _isManualSnifferActive) return;
            _isRadarBusy = true;
            try
            {
                var result = await Task.Run(() => PerformQuickHardwareProbe(true));
                UpdateLiveHardwareNotificationUi(result);

                if (isArrival && (result.HasCom || result.HasUsb))
                {
                    string devName = !string.IsNullOrEmpty(result.UsbName) ? result.UsbName : result.ComDesc;
                    string portStr = !string.IsNullOrEmpty(result.ComPort) ? $" on {result.ComPort}" : "";
                    AppendAutoHubLog($"[+] ⚡ SMART USB SNIFFER: Instant PnP Detection -> {devName}{portStr} ({result.UsbMode})");

                    if (!string.IsNullOrEmpty(result.ComPort) && result.UsbMode.Contains("MTK"))
                    {
                        _ = AutoLatchMtkBromPortAsync(result.ComPort, result.ComDesc);
                    }
                }
            }
            catch { }
            finally
            {
                _isRadarBusy = false;
            }
        }

        private void StartLiveHardwareRadar()

        {

            _liveHardwareRadarTimer = new DispatcherTimer

            {

                Interval = TimeSpan.FromMilliseconds(750)

            }
;

            _liveHardwareRadarTimer.Tick += OnHardwareRadarTick;

            _liveHardwareRadarTimer.Start();

        }




        private async void OnHardwareRadarTick(object? sender, EventArgs e)

        {

            if (_isRadarBusy || _isManualSnifferActive) return;

            _isRadarBusy = true;

            try

            {

                _fastbootAdbThrottleCounter++;

                bool checkCli = (_fastbootAdbThrottleCounter % 3 == 0);



                var result = await Task.Run(() => PerformQuickHardwareProbe(checkCli));

                if (!_isManualSnifferActive)

                {

                    UpdateLiveHardwareNotificationUi(result);

                }


            }


            catch { }

            finally

            {

                _isRadarBusy = false;

            }


        }




        private class HardwareRadarResult

        {

            public bool HasCom { get; set; }

            public string ComPort { get; set; } = "";

            public string ComDesc { get; set; } = "";

            public bool HasUsb { get; set; }

            public string UsbName { get; set; } = "";

            public string UsbMode { get; set; } = "";

            public string DeviceBrand { get; set; } = "";

            public string DeviceModel { get; set; } = "";

            public string DevicePlatform { get; set; } = "";

        }




        private HardwareRadarResult PerformQuickHardwareProbe(bool checkCli)

        {

            var res = new HardwareRadarResult();



            try

            {

                using var key = Registry.LocalMachine.OpenSubKey(@"HARDWARE\DEVICEMAP\SERIALCOMM");

                if (key != null)

                {

                    string bestPort = "";

                    string bestDesc = "";

                    string bestUsb = "";

                    string bestMode = "";

                    int bestScore = 0;



                    foreach (var val in key.GetValueNames())

                    {

                        string p = key.GetValue(val)?.ToString()?.Trim() ?? "";

                        if (string.IsNullOrEmpty(p)) continue;



                        var (desc, hwId) = FindPortDeviceDetails(p);

                        string combined = $"{val} {desc} {hwId} {p}".ToUpperInvariant();



                        int score = 1;

                        string mode = "SERIAL COM";

                        string usbName = string.IsNullOrEmpty(desc) ? p : desc;



                        if (combined.Contains("SPRD") || combined.Contains("U2S") || combined.Contains("SCI") || combined.Contains("1782"))

                        {

                            if (combined.Contains("DIAG") || combined.Contains("CALI"))

                            {

                                score = 10;

                                mode = "SPRD DIAG";

                                usbName = "SPRD U2S Diag (Calibration Port)";

                            }


                            else

                            {

                                score = 9;

                                mode = "UNISOC BROM";

                                usbName = "Unisoc Tiger BootROM (0x1782)";

                            }


                        }


                        else if (combined.Contains("0E8D") || combined.Contains("MEDIATEK") || combined.Contains("PRELOADER") || combined.Contains("MTK"))

                        {

                            score = 8;

                            mode = "MTK BROM";

                            usbName = "MediaTek High-Speed USB (0x0E8D)";

                        }


                        else if (combined.Contains("05C6") || combined.Contains("9008") || combined.Contains("QDLOADER") || combined.Contains("QUALCOMM"))

                        {

                            score = 8;

                            mode = "EDL 9008";

                            usbName = "Qualcomm HS-USB QDLoader 9008 (0x05C6)";

                        }


                        else if (combined.Contains("04E8") || combined.Contains("SAMSUNG"))

                        {

                            score = 7;

                            mode = "SAMSUNG USB";

                            usbName = "Samsung Mobile USB Modem (0x04E8)";

                        }


                        else if (combined.Contains("12D1") || combined.Contains("PCUI") || combined.Contains("HUAWEI"))

                        {

                            score = 7;

                            mode = "HUAWEI PCUI";

                            usbName = "Huawei PCUI / Kirin Interface (0x12D1)";

                        }




                        if (score > bestScore)

                        {

                            bestScore = score;

                            bestPort = p;

                            bestDesc = desc;

                            bestUsb = usbName;

                            bestMode = mode;

                        }


                    }




                    if (!string.IsNullOrEmpty(bestPort))
                    {
                        res.HasCom = true;
                        res.ComPort = bestPort;
                        res.ComDesc = string.IsNullOrEmpty(bestDesc) ? bestMode : bestDesc;
                        res.HasUsb = true;
                        res.UsbName = bestUsb;
                        res.UsbMode = bestMode;
                        _lastHardwareRadarResult = res;
                        return res;
                    }

                }

            }

            catch { }

            // If no serial port detected, check Fastboot or ADB via CLI
            if (!res.HasCom)
            {
                if (checkCli)
                {
                    bool foundUsb = false;
                    try
                    {
                        // Fastboot check
                        var fbPsi = new ProcessStartInfo(GetToolPath("fastboot.exe"), "devices")
                        {
                            RedirectStandardOutput = true,
                            UseShellExecute = false,
                            CreateNoWindow = true
                        }
;
                        using var fbProc = Process.Start(fbPsi);
                        if (fbProc != null)
                        {
                            string fbOut = fbProc.StandardOutput.ReadToEnd();
                            fbProc.WaitForExit(300);
                            if (!string.IsNullOrWhiteSpace(fbOut) && fbOut.Contains("fastboot"))
                            {
                                res.HasUsb = true;
                                res.UsbName = "Android Fastboot Bootloader (USB)";
                                res.UsbMode = "FASTBOOT";
                                foundUsb = true;
                            }

                        }


                        if (!foundUsb)
                        {
                            // ADB check
                            var adbPsi = new ProcessStartInfo(GetToolPath("adb.exe"), "devices -l")
                            {
                                RedirectStandardOutput = true,
                                UseShellExecute = false,
                                CreateNoWindow = true
                            }
;
                            using var adbProc = Process.Start(adbPsi);
                            if (adbProc != null)
                            {
                                string adbOut = adbProc.StandardOutput.ReadToEnd();
                                adbProc.WaitForExit(300);
                                if (adbOut.Contains("device\t") || adbOut.Contains("\tdevice") || adbOut.Contains(" device "))
                                {
                                    res.HasUsb = true;
                                    res.UsbName = "Android ADB Composite Interface (USB)";
                                    res.UsbMode = "ADB ACTIVE";
                                    foundUsb = true;

                                    // Extract primary active ADB serial to bind all subsequent CLI operations
                                    var adbLines = adbOut.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries);
                                    foreach (var aLine in adbLines)
                                    {
                                        if (aLine.Contains("\tdevice") || aLine.Contains(" device"))
                                        {
                                            var parts = aLine.Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries);
                                            if (parts.Length > 0 && !parts[0].Equals("List", StringComparison.OrdinalIgnoreCase))
                                            {
                                                _activeAdbSerial = parts[0].Trim();
                                                break;
                                            }
                                        }
                                    }

                                    // Extract live hardware model and product
                                    int modelIdx = adbOut.IndexOf("model:", StringComparison.OrdinalIgnoreCase);
                                    if (modelIdx >= 0)
                                    {
                                        string rem = adbOut.Substring(modelIdx + 6).Trim();
                                        int sp = rem.IndexOfAny(new[] { ' ', '\t', '\r', '\n' });
                                        string rawModel = sp > 0 ? rem.Substring(0, sp) : rem;
                                        res.DeviceModel = rawModel.Replace("_", " ").Trim();
                                    }


                                    int prodIdx = adbOut.IndexOf("product:", StringComparison.OrdinalIgnoreCase);
                                    if (prodIdx >= 0)
                                    {
                                        string rem = adbOut.Substring(prodIdx + 8).Trim();
                                        int sp = rem.IndexOfAny(new[] { ' ', '\t', '\r', '\n' });
                                        string rawProd = sp > 0 ? rem.Substring(0, sp) : rem;
                                        res.DevicePlatform = rawProd;
                                    }


                                    string upperModel = res.DeviceModel.ToUpperInvariant();
                                    string upperProd = res.DevicePlatform.ToUpperInvariant();
                                    if (upperModel.Contains("INFINIX") || upperProd.Contains("INFINIX") || upperModel.StartsWith("X6") || upperModel.StartsWith("X5")) res.DeviceBrand = "INFINIX";
                                    else if (upperModel.Contains("TECNO") || upperProd.Contains("TECNO")) res.DeviceBrand = "TECNO";
                                    else if (upperModel.Contains("CPH") || upperModel.Contains("OPPO")) res.DeviceBrand = "OPPO";
                                    else if (upperModel.Contains("V2") || upperModel.Contains("VIVO")) res.DeviceBrand = "VIVO";
                                    else if (upperModel.Contains("SM-") || upperModel.Contains("SAMSUNG") || upperModel.Contains("GALAXY")) res.DeviceBrand = "SAMSUNG";
                                    else if (upperModel.Contains("REDMI") || upperModel.Contains("XIAOMI") || upperModel.Contains("POCO")) res.DeviceBrand = "XIAOMI";
                                    else if (upperModel.Contains("ONEPLUS") || upperModel.Contains("KB") || upperModel.Contains("IN20")) res.DeviceBrand = "ONEPLUS";
                                    else if (upperModel.Contains("RMX") || upperModel.Contains("REALME")) res.DeviceBrand = "REALME";
                                    else if (!string.IsNullOrEmpty(res.DeviceModel)) res.DeviceBrand = "ANDROID";
                                }

                            }

                        }

                    }

                    catch { }

                    _lastHardwareRadarResult = res;
                }

                else
                {
                    // Retain previous active USB/ADB state during non-CLI ticks to prevent UI flickering / blinking
                    if (_lastHardwareRadarResult != null && _lastHardwareRadarResult.HasUsb && !_lastHardwareRadarResult.HasCom)
                    {
                        res.HasUsb = true;
                        res.UsbName = _lastHardwareRadarResult.UsbName;
                        res.UsbMode = _lastHardwareRadarResult.UsbMode;
                        res.DeviceBrand = _lastHardwareRadarResult.DeviceBrand;
                        res.DeviceModel = _lastHardwareRadarResult.DeviceModel;
                        res.DevicePlatform = _lastHardwareRadarResult.DevicePlatform;
                    }

                }

            }


            return res;

        }




