        private void TryInitNativeBridge()

        {

            try

            {

                bool initOk = BSLabBridge.BSLab_Initialize(_logCallback);

                if (initOk)

                {

                    AppendLog($"[+] Native Core Link established: {BSLabBridge.BSLab_GetVersion()}");

                }


            }


            catch (DllNotFoundException)

            {

                AppendLog($"[!] Note: BSLabCore.dll will be loaded dynamically from executable directory.");

            }


            catch (Exception ex)

            {

                AppendLog($"[!] Initialization notice: {ex.Message}");

            }


        }




        private void OnNativeLog(int level, string message)

        {

            Dispatcher.Invoke(() => AppendLog(message));

        }




        private void OnNativeProgress(int overallPct, int filePct, string partName, string statusText)
        {
            Dispatcher.Invoke(() =>
            {
                if (ProgressBar != null) ProgressBar.Value = overallPct;
                if (TxtProgressPct != null) TxtProgressPct.Text = $"{overallPct}%";
                if (TxtProgressStatus != null) TxtProgressStatus.Text = $"{partName}: {statusText}";

                if (ProgressBarUatFlasher != null) ProgressBarUatFlasher.Value = overallPct;
                if (TxtUatFlasherProgressPercent != null) TxtUatFlasherProgressPercent.Text = $"{overallPct}%";
                if (TxtUatFlasherProgressStatus != null) TxtUatFlasherProgressStatus.Text = $"{partName}: {statusText}";

                if (ProgressBarAutoHub != null) ProgressBarAutoHub.Value = overallPct;
                if (TxtAutoHubProgressStatus != null) TxtAutoHubProgressStatus.Text = $"{partName}: {statusText}";
            });
        }




        private static void SafeAppendWithCap(TextBox? textBox, string text, int maxChars = 200000, int trimChars = 50000)
        {
            if (textBox == null) return;
            try
            {
                if (textBox.Text.Length > maxChars)
                {
                    textBox.Text = textBox.Text.Substring(trimChars);
                }
                textBox.AppendText(text);
                textBox.ScrollToEnd();
            }
            catch { }
        }

        private void AppendLog(string message)
        {
            if (TxtLogConsole == null) return;
            if (!Dispatcher.CheckAccess())
            {
                Dispatcher.BeginInvoke(new Action(() => AppendLog(message)));
                return;
            }
            string time = DateTime.Now.ToString("HH:mm:ss");
            SafeAppendWithCap(TxtLogConsole, $"[{time}] {message}\n");
        }

