        private void AppendAutoHubLog(string message)
        {
            if (TxtAutoHubConsole == null) return;
            string time = DateTime.Now.ToString("HH:mm:ss");
            string entry = $"[{time}] {message}\n";

            Dispatcher.Invoke(() =>
            {
                SafeAppendWithCap(TxtAutoHubConsole, entry);

                if (FindName("TxtExecutionOverlayLog") is TextBox txtOverlay)
                {
                    SafeAppendWithCap(txtOverlay, entry);
                }
            });
        }




