        private Button? _currentActiveNavTab = null;

        private bool IsNavTabButton(FrameworkElement fe)
        {
            return fe == TabBtnAutoHub || fe == TabBtnAiAnalyse || fe == TabBtnMtk || fe == TabBtnQualcomm ||
                   fe == TabBtnFastboot || fe == TabBtnSamsung || fe == TabBtnUnisoc || fe == TabBtnHuawei ||
                   fe == TabBtnTestPoints || fe == TabBtnPartDoctor || fe == TabBtnBackup || fe == TabBtnSettings;
        }


        private void SetActiveNavTab(Button? activeBtn)
        {
            if (activeBtn != null)
            {
                _currentActiveNavTab = activeBtn;
            }

            else if (_currentActiveNavTab != null)
            {
                activeBtn = _currentActiveNavTab;
            }

            else
            {
                activeBtn = TabBtnAutoHub;
                _currentActiveNavTab = TabBtnAutoHub;
            }


            var regularStyle = (Style)FindResource("CyberNavTab");
            var activeStyle = (Style)FindResource("ActiveNavTab");
            var actBorder = (Brush)FindResource("ActiveNavTabBorder");
            var actFg = (Brush)FindResource("ActiveNavTabForeground");
            var actBg = (Brush)FindResource("ActiveNavTabBackground");
            var regFg = (Brush)FindResource("NavTabForeground");
            var regBg = (Brush)FindResource("NavTabBackground");

            var tabs = new[]
            {
                TabUatServices, TabUatFlasher, TabUatPartition, TabUatBackup, TabUatDiag, TabUatDump,
                TabBtnAutoHub, TabBtnAiAnalyse, TabBtnMtk, TabBtnQualcomm,
                TabBtnFastboot, TabBtnSamsung, TabBtnUnisoc, TabBtnHuawei,
                TabBtnTestPoints, TabBtnPartDoctor, TabBtnBackup, TabBtnSettings
            }
;

            foreach (var tab in tabs)
            {
                if (tab == null) continue;
                tab.ClearValue(Button.BackgroundProperty);
                tab.ClearValue(Button.ForegroundProperty);
                tab.ClearValue(Button.BorderBrushProperty);
                tab.ClearValue(Button.BorderThicknessProperty);
                tab.ClearValue(Button.FontWeightProperty);

                if (tab == activeBtn)
                {
                    tab.Style = activeStyle;
                    tab.BorderBrush = actBorder;
                    tab.Foreground = actFg;
                    tab.Background = actBg;
                    tab.BorderThickness = new Thickness(1);
                    tab.FontWeight = FontWeights.ExtraBold;
                }

                else
                {
                    tab.Style = regularStyle;
                }

            }

        }


        private void ResetTabStyles()
        {
            SetActiveNavTab(null);
        }

        public void HighlightSubTab(Button? activeBtn, params Button?[] allBtns)
        {
            if (activeBtn == null) return;

            var activeStyle = (Style)FindResource("SubTabButtonActive");
            var inactiveStyle = (Style)FindResource("SubTabButtonInactive");

            var activeBg = new SolidColorBrush(Color.FromRgb(2, 132, 199));     // #0284C7
            var activeBorder = new SolidColorBrush(Color.FromRgb(56, 189, 248)); // #38BDF8
            var activeFg = Brushes.White;

            var inactiveBg = new SolidColorBrush(Color.FromRgb(30, 41, 59));     // #1E293B
            var inactiveBorder = new SolidColorBrush(Color.FromRgb(51, 65, 85)); // #334155
            var inactiveFg = new SolidColorBrush(Color.FromRgb(148, 163, 184));  // #94A3B8

            foreach (var btn in allBtns)
            {
                if (btn == null) continue;

                if (btn == activeBtn)
                {
                    btn.Style = activeStyle;
                    btn.Background = activeBg;
                    btn.Foreground = activeFg;
                    btn.BorderBrush = activeBorder;
                    btn.BorderThickness = new Thickness(1.5);
                    btn.FontWeight = FontWeights.ExtraBold;
                    btn.Effect = new System.Windows.Media.Effects.DropShadowEffect
                    {
                        BlurRadius = 10,
                        ShadowDepth = 0,
                        Opacity = 0.65,
                        Color = Color.FromRgb(56, 189, 248)
                    };
                }
                else
                {
                    btn.Style = inactiveStyle;
                    btn.Background = inactiveBg;
                    btn.Foreground = inactiveFg;
                    btn.BorderBrush = inactiveBorder;
                    btn.BorderThickness = new Thickness(1);
                    btn.FontWeight = FontWeights.Bold;
                    btn.Effect = null;
                }
            }
        }

        public void HighlightBrandRibbonButton(string brandTag)
        {
            if (StackBrandRibbon == null) return;
            string bTag = brandTag.ToLower().Trim();

            foreach (var child in StackBrandRibbon.Children)
            {
                if (child is Button b)
                {
                    string childTag = (b.Tag as string ?? "").ToLower().Trim();
                    if (childTag == bTag)
                    {
                        b.BorderThickness = new Thickness(2);
                        b.BorderBrush = new SolidColorBrush(Color.FromRgb(0, 229, 255)); // Neon Cyan
                        b.Effect = new System.Windows.Media.Effects.DropShadowEffect
                        {
                            BlurRadius = 12,
                            ShadowDepth = 0,
                            Opacity = 0.9,
                            Color = Color.FromRgb(0, 229, 255)
                        };
                    }
                    else
                    {
                        b.BorderThickness = new Thickness(0);
                        b.BorderBrush = Brushes.Transparent;
                        b.Effect = null;
                    }
                }
            }
        }


        private void HideAllViews()
        {
            ViewAutoHub.Visibility = Visibility.Collapsed;
            if (FindName("ViewUatPartition") is FrameworkElement p) p.Visibility = Visibility.Collapsed;
            if (FindName("ViewUatFlasher") is FrameworkElement fl) fl.Visibility = Visibility.Collapsed;
            if (FindName("ViewUatBackup") is FrameworkElement bk) bk.Visibility = Visibility.Collapsed;
            if (FindName("ViewUatDiag") is FrameworkElement dg) dg.Visibility = Visibility.Collapsed;
            if (FindName("ViewUatDump") is FrameworkElement dm) dm.Visibility = Visibility.Collapsed;
            if (FindName("UatExecutionOverlay") is FrameworkElement ox) ox.Visibility = Visibility.Collapsed;
            ViewAiAnalyse.Visibility = Visibility.Collapsed;
            ViewMtk.Visibility = Visibility.Collapsed;
            ViewFastboot.Visibility = Visibility.Collapsed;
            ViewSamsung.Visibility = Visibility.Collapsed;
            ViewUnisoc.Visibility = Visibility.Collapsed;
            ViewHuawei.Visibility = Visibility.Collapsed;
            ViewBackup.Visibility = Visibility.Collapsed;
            ViewSettings.Visibility = Visibility.Collapsed;
        }


        private void OnNavTabClicked(object sender, RoutedEventArgs e)
        {
            if (sender is not Button btn) return;

            SetActiveNavTab(btn);
            HideAllViews();

            if (btn == TabUatServices || btn == TabBtnAutoHub)
            {
                ViewAutoHub.Visibility = Visibility.Visible;
                AppendAutoHubLog("[*] Switched Active Workspace: ⋮ SERVICES (Master Hardware Cockpit)");
            }

            else if (btn == TabUatFlasher)
            {
                if (FindName("ViewUatFlasher") is FrameworkElement fl) fl.Visibility = Visibility.Visible;
                if (_autoHubPartitions.Count == 0)
                {
                    LoadAutoHubSamplePartitions();
                }
                if (GridUatFlasherPartitions != null)
                {
                    GridUatFlasherPartitions.ItemsSource = null;
                    GridUatFlasherPartitions.ItemsSource = _autoHubPartitions;
                }
                UpdateUatFlasherCount();
                AppendAutoHubLog("[*] Switched Active Workspace: ⋮ FLASHER (Scatter & Firmware Flashing Engine)");
            }

            else if (btn == TabUatPartition || btn == TabBtnPartDoctor)
            {
                if (FindName("ViewUatPartition") is FrameworkElement pt) pt.Visibility = Visibility.Visible;
                if (_autoHubPartitions == null || _autoHubPartitions.Count == 0)
                {
                    LoadAutoHubSamplePartitions();
                }
                if (GridAutoHubPartitions != null)
                {
                    GridAutoHubPartitions.ItemsSource = null;
                    GridAutoHubPartitions.ItemsSource = _autoHubPartitions;
                }
                UpdateAutoHubPartCount();
                AppendAutoHubLog("[*] Switched Active Workspace: ⋮ PARTITION MANAGER (GPT Partition Doctor)");
            }

            else if (btn == TabUatBackup || btn == TabBtnBackup)
            {
                if (FindName("ViewUatBackup") is FrameworkElement bk) bk.Visibility = Visibility.Visible;
                RefreshBackupVault();
                AppendAutoHubLog("[*] Switched Active Workspace: ⋮ BACKUP FIRMWARE (Security & NV Vault)");
            }

            else if (btn == TabUatDiag)
            {
                if (FindName("ViewUatDiag") is FrameworkElement dg) dg.Visibility = Visibility.Visible;
                if (_uatDiagNvItems.Count == 0) InitializeUatDiagNvItems();
                if (GridUatDiagNvItems != null)
                {
