        private void LoadDefaultGptPartitions()
        {
            _partitions.Clear();
            // 100% Zero-Mock Guarantee: Do not inject fake/simulated partition lists into the UI.
            // Partitions will only be populated when read from the physical device via BROM, EDL, or Fastboot.
            if (GridPartitions != null)
            {
                GridPartitions.ItemsSource = null;
            }

            if (GridAutoHubPartitions != null && _autoHubPartitions.Count > 0)
            {
                GridAutoHubPartitions.ItemsSource = null;
                GridAutoHubPartitions.ItemsSource = _autoHubPartitions;
            }

            if (TxtPartCount != null)
            {
                TxtPartCount.Text = $" ({_autoHubPartitions.Count} Partitions Active)";
            }

        }


        
