        private async void OnFlashFirmwareClicked(object sender, RoutedEventArgs e)
        {
            string scatterFile = TxtScatterPath?.Text.Trim() ?? "";
            if (string.IsNullOrEmpty(scatterFile) || !File.Exists(scatterFile))
            {
                MessageBox.Show("Please select a valid MediaTek Scatter (.txt), OPPO (.ofp), or (.ozip) firmware file first.",
                    "Firmware Selection Required", MessageBoxButton.OK, MessageBoxImage.Information);
                OnBrowseScatterClicked(sender, e);
                return;
            }


            bool ok = false;
            _isManualSnifferActive = true;
            try
            {
                var (portOk, port) = await EnsureValidHardwarePortAsync(TxtPort?.Text);
                if (!portOk) return;

                string daPath = ResolveDaPath(TxtDaPath?.Text);
                AppendLog("══════════════════════════════════════════════════════════════");
                AppendLog($"⚡ FLASH FIRMWARE PIPELINE ENGAGED: {System.IO.Path.GetFileName(scatterFile)}");
                AppendLog("══════════════════════════════════════════════════════════════");
                AppendLog($"[*] Target Port       : {port}");
                AppendLog($"[*] Download Agent    : {System.IO.Path.GetFileName(daPath)}");

                string actualScatterFile = scatterFile;
                string ext = System.IO.Path.GetExtension(scatterFile).ToLowerInvariant();
                if (ext == ".ofp" || ext == ".ops" || ext == ".ozip")
                {
                    AppendLog($"[*] 🔐 Phase 4 Encrypted Container detected: {ext.ToUpperInvariant()}. Deploying On-The-Fly Decryptor...");
                    SetMtkProgress(10, "Auto-Decrypting OFP/OPS Package...");
                    string unpackOutDir = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "workspace", "extracted_" + System.IO.Path.GetFileNameWithoutExtension(scatterFile));
                    Directory.CreateDirectory(unpackOutDir);
                    string unpackerPy = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "engines", "unpackers", "ofp_ops_unpacker.py");
                    if (File.Exists(unpackerPy))
                    {
                        try
                        {
                            var psi = new ProcessStartInfo("python", $"\"{unpackerPy}\" --input \"{scatterFile}\" --out \"{unpackOutDir}\"")
                            {
                                RedirectStandardOutput = true,
                                UseShellExecute = false,
                                CreateNoWindow = true
                            };
                            using var proc = Process.Start(psi);
                            if (proc != null)
                            {
                                proc.WaitForExit(45000);
                                var scatters = Directory.GetFiles(unpackOutDir, "*scatter*.txt", SearchOption.AllDirectories);
                                if (scatters.Length > 0)
                                {
                                    actualScatterFile = scatters[0];
                                    AppendLog($"[+] ✅ Successfully Decrypted Container! Scatter located: {System.IO.Path.GetFileName(actualScatterFile)}");
                                }
                            }
                        }
                        catch (Exception unpackEx)
                        {
                            AppendLog($"[!] Auto-decrypt notice: {unpackEx.Message}. Proceeding with container target...");
                        }
                    }
                }

                AppendLog($"[*] Partition Engine  : Parsing Scatter Descriptor & Partition Offsets...");
                SetMtkProgress(20, "Deploying Download Agent (DA)...");

                await Task.Run(() =>
                {
                    try
                    {
                        // Clean single-pipeline invocation (loads DA on demand and streams partitions)
                        ok = BSLabBridge.BSLab_MTK_FlashFirmware(port, actualScatterFile, daPath, "", "", true, true, _progressCallback);
                    }
                    catch
                    {
                        ok = false;
                    }
                });
            }
            finally
            {
                _isManualSnifferActive = false;
            }

            if (ok)
            {
                SetMtkProgress(100, "Firmware Flashed Successfully");
                AppendLog("[+] ════════════ FIRMWARE FLASH COMPLETED ════════════");
                AppendLog($"[+] All firmware partition blocks successfully verified and written to device storage!");
                AppendLog("[+] Device rebooting to Android OS...");
            }

            else
            {
                SetMtkProgress(0, "Flashing Failed");
                AppendLog("[-] Firmware Flash Pipeline failed! Ensure device battery is charged and correct scatter firmware is selected.");
            }

        }


