        private void SetSubTabHighlight(Button activeBtn)
        {
            var activeBg = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(0x25, 0x63, 0xEB));
            var inactiveBg = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(0x1E, 0x29, 0x3B));
            var activeFg = System.Windows.Media.Brushes.White;
            var inactiveFg = new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(0x94, 0xA3, 0xB8));

            if (BtnSubTabFlash != null) { BtnSubTabFlash.Background = (activeBtn == BtnSubTabFlash) ? activeBg : inactiveBg; BtnSubTabFlash.Foreground = (activeBtn == BtnSubTabFlash) ? activeFg : inactiveFg; }
            if (BtnSubTabService != null) { BtnSubTabService.Background = (activeBtn == BtnSubTabService) ? activeBg : inactiveBg; BtnSubTabService.Foreground = (activeBtn == BtnSubTabService) ? activeFg : inactiveFg; }
            if (BtnSubTabPartitions != null) { BtnSubTabPartitions.Background = (activeBtn == BtnSubTabPartitions) ? new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(0x02, 0x84, 0xC7)) : inactiveBg; BtnSubTabPartitions.Foreground = (activeBtn == BtnSubTabPartitions) ? activeFg : inactiveFg; }
            if (BtnSubTabMetaDiag != null) { BtnSubTabMetaDiag.Background = (activeBtn == BtnSubTabMetaDiag) ? activeBg : inactiveBg; BtnSubTabMetaDiag.Foreground = (activeBtn == BtnSubTabMetaDiag) ? activeFg : inactiveFg; }
        }

