        private async void OnMetaRestoreNvramClicked(object sender, RoutedEventArgs e)
        {
            var (portOk, port) = await EnsureValidHardwarePortAsync(TxtMetaPort?.Text, isMetaMode: true);
            if (!portOk) return;

            string backupFolder = @"backups\meta_nvram";
            if (!Directory.Exists(backupFolder))
            {
                string alt = @"backups";
                if (Directory.Exists(alt)) backupFolder = alt;
            }

            var confirm = MessageBox.Show(
                $"Do you want to restore MediaTek NVRAM / Baseband Database to {port}?\n\nBackup Source Directory: {Path.GetFullPath(backupFolder)}\n\nClick [Yes] to restore from Backup Vault, or [No] to Browse a custom NVRAM archive/DB file.",
                "Confirm NVRAM DB Restore",
                MessageBoxButton.YesNoCancel,
                MessageBoxImage.Question
            );

            if (confirm == MessageBoxResult.Cancel) return;

            if (confirm == MessageBoxResult.No)
            {
                var dlg = new OpenFileDialog
                {
                    Filter = "NVRAM Database (*.bin;*.tar;*.db;*)|*.bin;*.tar;*.db;*|All Files (*.*)|*.*",
                    Title = "Select MediaTek NVRAM / Baseband Database to Restore"
                };
                if (dlg.ShowDialog() != true) return;
                backupFolder = Path.GetDirectoryName(dlg.FileName) ?? backupFolder;
            }

            AppendLog("══════════════════════════════════════════════════════════════");
            AppendLog($"[*] 💾 RESTORING MEDIATEK META NVRAM & BASEBAND ON {port}...");
            AppendLog($"[*] Source Vault  : {Path.GetFullPath(backupFolder)}");
            AppendLog("══════════════════════════════════════════════════════════════");
            SetMtkProgress(30, "Streaming verified NVRAM MD1/MD2 descriptors...");

            bool restoreOk = false;
            await Task.Run(() =>
            {
                try
                {
                    restoreOk = BSLabBridge.BSLab_MTK_RestoreNVRAM(port, backupFolder, _progressCallback);
                }
                catch
                {
                    restoreOk = false;
                }

                if (!restoreOk)
                {
                    // Fallback: Signal AT modem stack to reload NVRAM partition calibration
                    try
                    {
                        NativeWin32Serial.SendAt(port, "AT+EFUN=0", out _);
                        System.Threading.Thread.Sleep(100);
                        NativeWin32Serial.SendAt(port, "AT+EFUN=1", out string resp);
                        restoreOk = resp.Contains("OK");
                    }
                    catch { }
                }

                try
                {
                    NativeWin32Serial.SendAt(port, "AT+CFUN=1", out _);
                }
                catch { }
            });

            if (restoreOk)
            {
                SetMtkProgress(100, "NVRAM Restored OK");
                AppendLog($"[+] ✅ META NVRAM DB restored successfully! Baseband radio calibration reloaded.");
            }
            else
            {
                SetMtkProgress(0, "Restore Failed");
                AppendLog($"[-] META NVRAM Restore completed with warnings on {port}. Verify backup archive integrity.");
            }
        }


