        private string GetToolPath(string exeName)

        {

            string p1 = System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "resources", "platform-tools", exeName);

            if (File.Exists(p1)) return p1;

            string p2 = @"C:\BSLab_Tool\resources\platform-tools\" + exeName;

            if (File.Exists(p2)) return p2;

            return exeName;

        }

        private string _activeAdbSerial = "";

        private async Task<string> ExecuteCliAsync(string exeName, string arguments)
        {
            if (_isOperationCancelled) return "[-] Operation cancelled by Technician.";

            // Intelligent ADB Serial Binding to prevent "more than one device/emulator"
            if (exeName.Contains("adb", StringComparison.OrdinalIgnoreCase))
            {
                string trimmedArgs = arguments?.TrimStart() ?? "";
                if (!string.IsNullOrEmpty(_activeAdbSerial) &&
                    !trimmedArgs.StartsWith("-s ", StringComparison.OrdinalIgnoreCase) &&
                    !trimmedArgs.StartsWith("devices", StringComparison.OrdinalIgnoreCase) &&
                    !trimmedArgs.StartsWith("kill-server", StringComparison.OrdinalIgnoreCase) &&
                    !trimmedArgs.StartsWith("start-server", StringComparison.OrdinalIgnoreCase) &&
                    !trimmedArgs.StartsWith("version", StringComparison.OrdinalIgnoreCase) &&
                    !trimmedArgs.StartsWith("connect", StringComparison.OrdinalIgnoreCase) &&
                    !trimmedArgs.StartsWith("disconnect", StringComparison.OrdinalIgnoreCase))
                {
                    arguments = $"-s {_activeAdbSerial} {arguments}";
                }
            }

            string tool = GetToolPath(exeName);

            return await Task.Run(() =>

            {

                try

                {

                    if (_isOperationCancelled) return "[-] Operation cancelled by Technician.";

                    var psi = new ProcessStartInfo

                    {

                        FileName = tool,

                        Arguments = arguments,

                        RedirectStandardOutput = true,

                        RedirectStandardError = true,

                        UseShellExecute = false,

                        CreateNoWindow = true

                    }
;

                    using var proc = Process.Start(psi);
                    if (proc == null) return "Failed to start process.";
                    _activeChildProcess = proc;

                    var stdoutTask = proc.StandardOutput.ReadToEndAsync();
                    var stderrTask = proc.StandardError.ReadToEndAsync();

                    bool exited = proc.WaitForExit(15000);
                    if (!exited || _isOperationCancelled)
                    {
                        try { proc.Kill(entireProcessTree: true); } catch { }
                        _activeChildProcess = null;
                        return _isOperationCancelled ? "[-] Operation cancelled by Technician." : "[-] CLI Process timed out (15s).";
                    }

                    _activeChildProcess = null;
                    string stdout = stdoutTask.GetAwaiter().GetResult();
                    string stderr = stderrTask.GetAwaiter().GetResult();
                    return string.IsNullOrWhiteSpace(stderr) ? stdout.Trim() : $"{stdout.Trim()}\n{stderr.Trim()}".Trim();

                }


                catch (Exception ex)

                {

                    return $"[!] CLI Execution Error: {ex.Message}";

                }


            }
);

        }




