        private static bool ValidateLuhn15(string imei, out string cleanImei)
        {
            cleanImei = Regex.Replace(imei ?? "", @"[^\d]", "");
            if (cleanImei.Length != 15) return false;

            int sum = 0;
            for (int i = 0; i < 14; i++)
            {
                int digit = cleanImei[i] - '0';
                if (i % 2 == 1)
                {
                    digit *= 2;
                    if (digit > 9) digit -= 9;
                }
                sum += digit;
            }
            int check = (10 - (sum % 10)) % 10;
            return check == (cleanImei[14] - '0');
        }

        private static string CalculateLuhnCheckDigit(string prefix14)
        {
            int sum = 0;
            for (int i = 0; i < 14; i++)
            {
                int digit = prefix14[i] - '0';
                if (i % 2 == 1)
                {
                    digit *= 2;
                    if (digit > 9) digit -= 9;
                }
                sum += digit;
            }
            return ((10 - (sum % 10)) % 10).ToString();
        }

        private void OnAdbGenerateImeiClicked(object sender, RoutedEventArgs e)
        {
            var rand = new Random();
            string prefix = "86746205" + rand.Next(100000, 999999).ToString("D6");
            string imei1 = prefix + CalculateLuhnCheckDigit(prefix);

            string prefix2 = "86746205" + rand.Next(100000, 999999).ToString("D6");
            string imei2 = prefix2 + CalculateLuhnCheckDigit(prefix2);

            if (TxtAdbImei1 != null) TxtAdbImei1.Text = imei1;
            if (TxtAdbImei2 != null) TxtAdbImei2.Text = imei2;

            AppendAdbLog($"[+] Generated Valid Luhn IMEI 1: {imei1}");
            AppendAdbLog($"[+] Generated Valid Luhn IMEI 2: {imei2}");
        }

