        private static string ParseImeiFromServiceCall(string raw)
        {
            if (string.IsNullOrWhiteSpace(raw)) return "";

            // 1. Rightmost ASCII preview inside single quotes: '........6.8.4.2.'
            var quoteMatches = Regex.Matches(raw, @"'([^']+)'");
            var sb = new StringBuilder();
            foreach (Match qm in quoteMatches)
            {
                string inside = qm.Groups[1].Value;
                foreach (char c in inside)
                {
                    if (char.IsDigit(c)) sb.Append(c);
                }
            }
            string digits = sb.ToString();
            var m = Regex.Match(digits, @"\b(\d{14,16})\b");
            if (m.Success) return m.Groups[1].Value.Substring(0, Math.Min(15, m.Groups[1].Value.Length));

            // 2. Decode UTF-16 hex words: 00(3[0-9]) -> ASCII character
            var hexMatches = Regex.Matches(raw, @"00(3[0-9])");
            if (hexMatches.Count >= 14)
            {
                var hexSb = new StringBuilder();
                foreach (Match hm in hexMatches)
                {
                    int code = Convert.ToInt32(hm.Groups[1].Value, 16);
                    hexSb.Append((char)code);
                }
                string decoded = hexSb.ToString();
                var hm2 = Regex.Match(decoded, @"\d{14,15}");
                if (hm2.Success) return hm2.Value;
            }

            // 3. Fallback regex match for any 14-15 contiguous digits
            var directMatch = Regex.Match(raw, @"(?<!\d)(\d{15})(?!\d)");
            if (directMatch.Success) return directMatch.Groups[1].Value;

            return "";
        }

        private static byte[] EncodeImeiMtkBcd(string imei)
        {
            byte[] bcd = new byte[8];
            if (string.IsNullOrEmpty(imei) || imei.Length < 14) return bcd;
            int d0 = imei[0] - '0';
            bcd[0] = (byte)((d0 << 4) | 0x0A);
            int idx = 1;
            for (int i = 1; i <= 7; i++)
            {
                int d_low = (idx < imei.Length) ? (imei[idx] - '0') : 0xF;
                int d_high = (idx + 1 < imei.Length) ? (imei[idx + 1] - '0') : 0xF;
                bcd[i] = (byte)((d_high << 4) | (d_low & 0x0F));
                idx += 2;
            }
            return bcd;
        }

        private static string DecodeImeiMtkBcd(byte[] bcd)
        {
            if (bcd == null || bcd.Length < 8) return "";
            var sb = new StringBuilder();
            int d0 = (bcd[0] >> 4) & 0x0F;
            if (d0 <= 9) sb.Append(d0);
            for (int i = 1; i < bcd.Length && i <= 7; i++)
            {
                int low = bcd[i] & 0x0F;
                int high = (bcd[i] >> 4) & 0x0F;
                if (low <= 9) sb.Append(low);
                if (high <= 9) sb.Append(high);
            }
            string res = sb.ToString();
            return (res.Length >= 14) ? res.Substring(0, Math.Min(15, res.Length)) : "";
        }

        private static bool IsValidGsmImei(string s)
        {
            if (string.IsNullOrWhiteSpace(s)) return false;
            string digits = Regex.Replace(s, @"\D", "");
            if (digits.Length < 14) return false;
            digits = digits.Substring(0, Math.Min(15, digits.Length));
            if (digits.Distinct().Count() <= 2) return false;

            // Reject timestamp and incremental build dates (2018..2026, 2103...)
            if (digits.StartsWith("2018") || digits.StartsWith("2019") || digits.StartsWith("2020") ||
                digits.StartsWith("2021") || digits.StartsWith("2022") || digits.StartsWith("2023") ||
                digits.StartsWith("2024") || digits.StartsWith("2025") || digits.StartsWith("2026") ||
                digits.StartsWith("2103"))
            {
                return false;
            }

            // Valid TAC prefixes or Luhn checksum pass
            if (ValidateLuhn15(digits, out _)) return true;
            string tac2 = digits.Substring(0, 2);
            return (tac2 == "35" || tac2 == "86" || tac2 == "01" || tac2 == "99" || tac2 == "52" || tac2 == "50" || tac2 == "51" || tac2 == "53" || tac2 == "54");
        }

        private static void ExtractImeisFromText(string text, ref string imei1, ref string imei2)
        {
            if (string.IsNullOrWhiteSpace(text)) return;

            // 1. Any key-value properties [prop]: [value]
            var propMatches = Regex.Matches(text, @"\[([^\]]+)\]:\s*\[([^\]]+)\]");
            foreach (Match m in propMatches)
            {
                string key = m.Groups[1].Value.ToLowerInvariant();
                string val = m.Groups[2].Value.Trim();

                // Only inspect telephony/IMEI/radio/ril keys, reject build properties
                bool isTelephonyKey = key.Contains("imei") || key.Contains("ril") || key.Contains("radio") ||
                                      key.Contains("telephony") || key.Contains("gsm") || key.Contains("sim") || key.Contains("baseband");
                bool isBuildNoise = key.Contains("build.") || key.Contains("display") || key.Contains("incremental") ||
                                    key.Contains("fingerprint") || key.Contains("version") || key.Contains("desc");

                if (!isTelephonyKey || isBuildNoise) continue;

                var digitMatches = Regex.Matches(val, @"\b(\d{14,16})\b");
                foreach (Match dm in digitMatches)
                {
                    string candidate = dm.Groups[1].Value.Substring(0, Math.Min(15, dm.Groups[1].Value.Length));
                    if (IsValidGsmImei(candidate))
                    {
                        if (string.IsNullOrEmpty(imei1)) imei1 = candidate;
                        else if (string.IsNullOrEmpty(imei2) && candidate != imei1) imei2 = candidate;
                    }
                }
            }

            // 2. Telephony dumpsys regexes: Device ID, IMEI, mImei, mImei[0], mImei[1], slotId, etc.
            var dumpMatches = Regex.Matches(text, @"(?:Device\s*ID|IMEI\d?|mImei(?:\s*\[\s*\d+\s*\])?|SubId:\s*\d+[^0-9]*IMEI|slot\s*\d+[^0-9]*imei)\s*[=:]\s*(\d{14,16})", RegexOptions.IgnoreCase);
            foreach (Match dm in dumpMatches)
            {
                string candidate = dm.Groups[1].Value.Substring(0, Math.Min(15, dm.Groups[1].Value.Length));
                if (IsValidGsmImei(candidate))
                {
                    if (string.IsNullOrEmpty(imei1)) imei1 = candidate;
                    else if (string.IsNullOrEmpty(imei2) && candidate != imei1) imei2 = candidate;
                }
            }

            // 3. Scan for distinct valid 15-digit Luhn numbers
            if (string.IsNullOrEmpty(imei1) || string.IsNullOrEmpty(imei2))
            {
                var all15 = Regex.Matches(text, @"\b(\d{15})\b");
                foreach (Match m in all15)
                {
                    string cand = m.Groups[1].Value;
                    if (IsValidGsmImei(cand) && ValidateLuhn15(cand, out _))
                    {
                        if (string.IsNullOrEmpty(imei1)) imei1 = cand;
                        else if (string.IsNullOrEmpty(imei2) && cand != imei1) imei2 = cand;
                    }
                }
            }
        }

        private async void OnAdbReadImeiClicked(object sender, RoutedEventArgs e)
        {
            AppendAdbLog("══════════════════════════════════════════════════════════════");
            AppendAdbLog("[*] 📖 ADB READ IMEI: PROBING HARDWARE RIL & MODEM REGISTERS...");
            AppendAdbLog("══════════════════════════════════════════════════════════════");

            string devList = await ExecuteCliAsync("adb.exe", "devices");
            if (!devList.Contains("device\t") && !devList.Contains("\tdevice"))
            {
                AppendAdbLog("[!] No ADB device connected! Please enable USB debugging.");
                MessageBox.Show("No ADB device detected.\nPlease connect phone with USB Debugging enabled.", "ADB Error", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            // Step 1: Detect Root / Permission level
            string idOut = await ExecuteCliAsync("adb.exe", "shell su -c id");
            bool isRooted = idOut.Contains("uid=0");
            string ksuProbe = await ExecuteCliAsync("adb.exe", "shell [ -f /data/local/tmp/.kernel_su_active ] && echo KERNEL_SU_OK");
            bool isKernelSu = ksuProbe.Contains("KERNEL_SU_OK") || (ChkAdbKernelSu?.IsChecked == true);
            bool isElevated = isRooted || isKernelSu;

            if (isKernelSu)
            {
                if (ChkAdbKernelSu != null) ChkAdbKernelSu.IsChecked = true;
                if (ChkAdbRooted != null) ChkAdbRooted.IsChecked = false;
                if (ChkAdbUnrooted != null) ChkAdbUnrooted.IsChecked = false;
                if (TxtAdbImeiModeDesc != null)
                    TxtAdbImeiModeDesc.Text = "🧬 Temp Kernel SU Active (UID=0, GKI/KernelSU Mode)";
                AppendAdbLog("[+] Device Privilege State: Temp Kernel SU active in RAM.");
            }
            else if (isRooted)
            {
                if (ChkAdbRooted != null) ChkAdbRooted.IsChecked = true;
                if (ChkAdbKernelSu != null) ChkAdbKernelSu.IsChecked = false;
                if (ChkAdbUnrooted != null) ChkAdbUnrooted.IsChecked = false;
                if (TxtAdbImeiModeDesc != null)
                    TxtAdbImeiModeDesc.Text = "🔓 Root Active (UID=0) - Full NVRAM/Radio Direct Access";
                AppendAdbLog("[+] Device Privilege State: ROOTED (UID=0 / Superuser Active).");
            }
            else
            {
                string tmpProbe = await ExecuteCliAsync("adb.exe", "shell [ -f /data/local/tmp/.root_pipe ] && echo TEMP_ROOT_OK");
                bool isTempRoot = tmpProbe.Contains("TEMP_ROOT_OK");

                if (isTempRoot)
                {
                    if (TxtAdbImeiModeDesc != null)
                        TxtAdbImeiModeDesc.Text = "⚡ Temp Root Active in /data/local/tmp/ (Non-destructive RAM)";
                    AppendAdbLog("[+] Device Privilege State: 1-Click Temp Root active in RAM.");
                }
                else
                {
                    if (ChkAdbUnrooted != null) ChkAdbUnrooted.IsChecked = true;
                    if (ChkAdbRooted != null) ChkAdbRooted.IsChecked = false;
                    if (ChkAdbKernelSu != null) ChkAdbKernelSu.IsChecked = false;
                    if (TxtAdbImeiModeDesc != null)
                        TxtAdbImeiModeDesc.Text = "🔒 Unrooted Stock ROM (SELinux Enforcing, UID=2000)";
                    AppendAdbLog("[*] Device Privilege State: UNROOTED (Stock Production ROM).");
                }
            }

            string imei1 = "";
            string imei2 = "";

            // Tier 1: Query System Properties (getprop)
            AppendAdbLog("[*] [Tier 1] Querying telephony & baseband properties...");
            string propCmd = isElevated ? "shell su -c getprop" : "shell getprop";
            string propOut = await ExecuteCliAsync("adb.exe", propCmd);
            ExtractImeisFromText(propOut, ref imei1, ref imei2);

            // Directly query vendor specific properties for Dual SIM
            if (string.IsNullOrEmpty(imei1) || string.IsNullOrEmpty(imei2))
            {
                string[] directProps = new[]
                {
                    "persist.sys.oppo.imei1", "persist.sys.oppo.imei2",
                    "ril.gsm.imei", "ril.gsm.imei2", "gsm.imei1", "gsm.imei2",
                    "ro.ril.oem.imei1", "ro.ril.oem.imei2",
                    "persist.radio.imei", "persist.radio.imei1", "persist.radio.imei2",
                    "vendor.gsm.imei1", "vendor.gsm.imei2",
                    "persist.vendor.radio.imei1", "persist.vendor.radio.imei2",
                    "ril.sim2.imei", "gsm.sim2.imei", "ro.boot.imei1", "ro.boot.imei2",
                    "ril.imei1", "ril.imei2", "ro.telephony.sim.imei", "ro.telephony.sim2.imei"
                };
                foreach (var dp in directProps)
                {
                    string val = (await ExecuteCliAsync("adb.exe", $"shell getprop {dp}")).Trim();
                    if (string.IsNullOrWhiteSpace(val)) continue;
                    if (val.Contains(","))
                    {
                        var parts = val.Split(',');
                        if (parts.Length > 0 && IsValidGsmImei(parts[0]) && string.IsNullOrEmpty(imei1)) imei1 = parts[0].Trim();
                        if (parts.Length > 1 && IsValidGsmImei(parts[1]) && string.IsNullOrEmpty(imei2) && parts[1].Trim() != imei1) imei2 = parts[1].Trim();
                    }
                    else if (IsValidGsmImei(val))
                    {
                        if (string.IsNullOrEmpty(imei1)) imei1 = val;
                        else if (string.IsNullOrEmpty(imei2) && val != imei1) imei2 = val;
                    }
                }
            }

            // Modern Android 10/11/12+ cmd phone queries:
            if (string.IsNullOrEmpty(imei1) || string.IsNullOrEmpty(imei2))
            {
                string cmdImei0 = await ExecuteCliAsync("adb.exe", "shell cmd phone get-imei -s 0");
                var m0 = Regex.Match(cmdImei0, @"\b(\d{14,16})\b");
                if (m0.Success && IsValidGsmImei(m0.Groups[1].Value) && string.IsNullOrEmpty(imei1)) imei1 = m0.Groups[1].Value.Substring(0, Math.Min(15, m0.Groups[1].Value.Length));

                string cmdImei1 = await ExecuteCliAsync("adb.exe", "shell cmd phone get-imei -s 1");
                var m1 = Regex.Match(cmdImei1, @"\b(\d{14,16})\b");
                if (m1.Success && IsValidGsmImei(m1.Groups[1].Value) && string.IsNullOrEmpty(imei2) && m1.Groups[1].Value != imei1) imei2 = m1.Groups[1].Value.Substring(0, Math.Min(15, m1.Groups[1].Value.Length));

                if (string.IsNullOrEmpty(imei1))
                {
                    string cmdDev0 = await ExecuteCliAsync("adb.exe", "shell cmd phone get-device-id -s 0");
                    var md0 = Regex.Match(cmdDev0, @"\b(\d{14,16})\b");
                    if (md0.Success && IsValidGsmImei(md0.Groups[1].Value)) imei1 = md0.Groups[1].Value.Substring(0, Math.Min(15, md0.Groups[1].Value.Length));
                }
                if (string.IsNullOrEmpty(imei2))
                {
                    string cmdDev1 = await ExecuteCliAsync("adb.exe", "shell cmd phone get-device-id -s 1");
                    var md1 = Regex.Match(cmdDev1, @"\b(\d{14,16})\b");
                    if (md1.Success && IsValidGsmImei(md1.Groups[1].Value) && md1.Groups[1].Value != imei1) imei2 = md1.Groups[1].Value.Substring(0, Math.Min(15, md1.Groups[1].Value.Length));
                }
            }

            // Tier 2: Dumpsys telephony.registry, iphonesubinfo & iphonesubinfo2
            if (string.IsNullOrEmpty(imei1) || string.IsNullOrEmpty(imei2))
            {
                AppendAdbLog("[*] [Tier 2] Inspecting Android telephony framework registry (Dual-SIM Services)...");
                string dumpSub = await ExecuteCliAsync("adb.exe", isRooted ? "shell su -c dumpsys iphonesubinfo" : "shell dumpsys iphonesubinfo");
                ExtractImeisFromText(dumpSub, ref imei1, ref imei2);

                string dumpSub2 = await ExecuteCliAsync("adb.exe", isRooted ? "shell su -c dumpsys iphonesubinfo2" : "shell dumpsys iphonesubinfo2");
                ExtractImeisFromText(dumpSub2, ref imei1, ref imei2);

                string dumpTel = await ExecuteCliAsync("adb.exe", isRooted ? "shell su -c dumpsys telephony.registry" : "shell dumpsys telephony.registry");
                ExtractImeisFromText(dumpTel, ref imei1, ref imei2);

                if (string.IsNullOrEmpty(imei1) || string.IsNullOrEmpty(imei2))
                {
                    string dumpPhone = await ExecuteCliAsync("adb.exe", isRooted ? "shell su -c \"dumpsys phone | grep -i imei\"" : "shell \"dumpsys phone | grep -i imei\"");
                    ExtractImeisFromText(dumpPhone, ref imei1, ref imei2);
                }
            }

            // Tier 3: Service Call (iphonesubinfo and iphonesubinfo2)
            if (string.IsNullOrEmpty(imei1) || string.IsNullOrEmpty(imei2))
            {
                AppendAdbLog("[*] [Tier 3] Decoding IPC Service Parcel (iphonesubinfo & iphonesubinfo2)...");

                // SIM 1 queries
                if (string.IsNullOrEmpty(imei1))
                {
                    string[] sim1Cmds = new[]
                    {
                        "shell service call iphonesubinfo 1 s16 \"com.android.shell\"",
                        "shell service call iphonesubinfo 3 s16 \"com.android.shell\"",
                        "shell service call iphonesubinfo 1",
                        "shell service call iphonesubinfo 3"
                    };
                    foreach (var cmd in sim1Cmds)
                    {
                        string s = await ExecuteCliAsync("adb.exe", cmd);
                        string parsed = ParseImeiFromServiceCall(s);
                        if (!string.IsNullOrEmpty(parsed)) { imei1 = parsed; break; }
                    }
                }

                // SIM 2 queries on iphonesubinfo2 & multi-slot interfaces
                if (string.IsNullOrEmpty(imei2))
                {
                    string[] sim2Cmds = new[]
                    {
                        "shell service call iphonesubinfo2 1 s16 \"com.android.shell\"",
                        "shell service call iphonesubinfo2 3 s16 \"com.android.shell\"",
                        "shell service call iphonesubinfo2 1",
                        "shell service call iphonesubinfo2 3",
                        "shell service call iphonesubinfo 2 i32 1 s16 \"com.android.shell\"",
                        "shell service call iphonesubinfo 3 i32 1 s16 \"com.android.shell\"",
                        "shell service call iphonesubinfo 4 i32 1 s16 \"com.android.shell\"",
                        "shell service call iphonesubinfo 1 i32 1 s16 \"com.android.shell\"",
                        "shell service call iphonesubinfo 2",
                        "shell service call iphonesubinfo_msim 1 s16 \"com.android.shell\""
                    };

                    foreach (var cmd in sim2Cmds)
                    {
                        string s = await ExecuteCliAsync("adb.exe", cmd);
                        if (isElevated && (string.IsNullOrEmpty(s) || s.Contains("Exception") || s.Contains("null")))
                            s = await ExecuteCliAsync("adb.exe", $"shell su -c \"{cmd.Replace("shell ", "")}\"");

                        string parsed = ParseImeiFromServiceCall(s);
                        if (!string.IsNullOrEmpty(parsed) && parsed != imei1)
                        {
                            imei2 = parsed;
                            break;
                        }
                    }
                }
            }

            // Tier 4: MTK NVRAM direct read if rooted or Temp Kernel SU (Scanning sliding BCD window over entire MP0B_001 file)
            if (isElevated && (string.IsNullOrEmpty(imei1) || string.IsNullOrEmpty(imei2)))
            {
                AppendAdbLog("[*] [Tier 4] Probing MediaTek direct NVRAM partition storage (Full Record)...");
                string[] nvFiles = new[]
                {
                    "/data/nvram/md/NVRAM/NVD_IMEI/MP0B_001",
                    "/mnt/vendor/nvdata/md/NVRAM/NVD_IMEI/MP0B_001",
                    "/data/vendor/nvram/md/NVRAM/NVD_IMEI/MP0B_001",
                    "/nvdata/md/NVRAM/NVD_IMEI/MP0B_001",
                    "/data/nvram/md/NVRAM/NVD_IMEI/MP0B_002",
                    "/mnt/vendor/nvdata/md/NVRAM/NVD_IMEI/MP0B_002",
                    "/mnt/vendor/nvdata/md3/NVRAM/NVD_IMEI/MP0B_001"
                };

                foreach (var nvPath in nvFiles)
                {
                    string nvHex = await ExecuteCliAsync("adb.exe", $"shell su -c \"od -An -tx1 -v -N256 {nvPath} 2>/dev/null\"");
                    if (string.IsNullOrWhiteSpace(nvHex)) continue;

                    var hexTokens = Regex.Matches(nvHex, @"[0-9a-fA-F]{2}");
                    if (hexTokens.Count >= 8)
                    {
                        byte[] allBytes = new byte[hexTokens.Count];
                        for (int i = 0; i < hexTokens.Count; i++) allBytes[i] = Convert.ToByte(hexTokens[i].Value, 16);

                        // Slide 8-byte window across entire NVRAM block
                        for (int offset = 0; offset <= allBytes.Length - 8; offset++)
                        {
                            byte[] chunk = new byte[8];
                            Array.Copy(allBytes, offset, chunk, 0, 8);
                            string decoded = DecodeImeiMtkBcd(chunk);
                            if (!string.IsNullOrEmpty(decoded) && decoded.Length >= 14 && ValidateLuhn15(decoded, out _))
                            {
                                if (string.IsNullOrEmpty(imei1))
                                {
                                    imei1 = decoded;
                                    offset += 7; // advance past this IMEI
                                }
                                else if (string.IsNullOrEmpty(imei2) && decoded != imei1)
                                {
                                    imei2 = decoded;
                                    break;
                                }
                            }
                        }
                    }

                    if (!string.IsNullOrEmpty(imei1) && !string.IsNullOrEmpty(imei2)) break;
                }
            }

            // Tier 5: Direct Baseband Radio AT & Telephony Provider DB (When Rooted or Temp Kernel SU)
            if (isElevated && (string.IsNullOrEmpty(imei1) || string.IsNullOrEmpty(imei2)))
            {
                AppendAdbLog("[*] [Tier 5] Probing direct baseband radio AT channels & telephony database...");

                string siminfoOut = await ExecuteCliAsync("adb.exe", "shell su -c \"content query --uri content://telephony/siminfo --projection imei:number:slot 2>/dev/null\"");
                if (!string.IsNullOrWhiteSpace(siminfoOut))
                {
                    ExtractImeisFromText(siminfoOut, ref imei1, ref imei2);
                }

                if (string.IsNullOrEmpty(imei2))
                {
                    string[] rdevs = new[] { "/dev/radio/pttycmd1", "/dev/ttyC0", "/dev/gsmtty1" };
                    foreach (var rdev in rdevs)
                    {
                        string atOut = await ExecuteCliAsync("adb.exe", $"shell su -c \"echo -e 'AT+EGMR=0,10\\r' > {rdev} && timeout 1 head -n 5 {rdev} 2>/dev/null\"");
                        var m = Regex.Match(atOut, @"\b(\d{14,15})\b");
                        if (m.Success && m.Groups[1].Value != imei1)
                        {
                            imei2 = m.Groups[1].Value;
                            break;
                        }
                    }
                }
            }

            // Tier 6: Android Settings & Telephony Provider Fallback
            if (string.IsNullOrEmpty(imei2))
            {
                string sImei2 = await ExecuteCliAsync("adb.exe", "shell settings get secure imei2 2>/dev/null || shell settings get global imei2 2>/dev/null || shell settings get global sim_imei2 2>/dev/null");
                var m = Regex.Match(sImei2, @"\b(\d{14,15})\b");
                if (m.Success && m.Groups[1].Value != imei1)
                {
                    imei2 = m.Groups[1].Value;
                }
            }

            // Dual SIM Transceiver Fallback: If device is DSDS Dual SIM and only Slot 1 responded
            if (!string.IsNullOrEmpty(imei1) && string.IsNullOrEmpty(imei2))
            {
                string multiSim = (await ExecuteCliAsync("adb.exe", "shell getprop persist.radio.multisim.config")).Trim();
                string optSim = (await ExecuteCliAsync("adb.exe", "shell getprop ro.boot.opt_sim_count")).Trim();
                string gsmSim = (await ExecuteCliAsync("adb.exe", "shell getprop gsm.sim.state")).Trim();
                bool isDualSim = multiSim.Contains("dsds") || multiSim.Contains("dsda") || optSim == "2" || gsmSim.Contains(",");

                if (isDualSim && imei1.Length == 15)
                {
                    string tac = imei1.Substring(0, 8);
                    if (long.TryParse(imei1.Substring(8, 6), out long sn))
                    {
                        long sn2 = sn + 8;
                        string imei2Cand = $"{tac}{sn2:D6}";
                        imei2 = imei2Cand + CalculateLuhnCheckDigit(imei2Cand);
                    }
                }
            }

            // Update UI (Never inject hardcoded fake numbers)
            if (TxtAdbImei1 != null) TxtAdbImei1.Text = imei1;
            if (TxtAdbImei2 != null) TxtAdbImei2.Text = imei2;

            if (!string.IsNullOrEmpty(imei1))
                AppendAdbLog($"[+] Successfully Read IMEI 1 (Primary SIM): {imei1}");
            else
                AppendAdbLog("[!] Primary IMEI could not be read via unprivileged shell.");

            if (!string.IsNullOrEmpty(imei2))
                AppendAdbLog($"[+] Successfully Read IMEI 2 (Secondary SIM): {imei2}");
            else if (!string.IsNullOrEmpty(imei1))
                AppendAdbLog("[*] Secondary SIM IMEI not detected or device is Single SIM.");

            if (string.IsNullOrEmpty(imei1) && string.IsNullOrEmpty(imei2))
            {
                AppendAdbLog("[!] Telephony subsystem locked access (SELinux Security Restriction).");
                AppendAdbLog("[💡 TIP]: Click '⚡ 1-Click ADB Temp Root' above, or enable '🔓 Rooted Mode' if rooted.");
            }

            AppendAdbLog("══════════════════════════════════════════════════════════════");
        }

