        private async Task<string> SendSerialAtCommandAsync(string portName, string command, int timeoutMs = 1500)

        {

            if (string.IsNullOrWhiteSpace(portName) || portName == "AUTO" || portName.Contains("No COM"))

                return "[-] No valid COM port selected.";



            return await Task.Run(() =>

            {

                try

                {

                    string cleanPort = portName.Split(' ', '(', ')')[0].Trim();

                    if (!cleanPort.StartsWith("COM", StringComparison.OrdinalIgnoreCase))

                    {

                        var m = Regex.Match(portName, @"(COM\d+)");

                        if (m.Success) cleanPort = m.Groups[1].Value;

                    }




                    var psi = new ProcessStartInfo

                    {

                        FileName = "powershell.exe",

                        Arguments = $"-NoProfile -Command \"$p = New-Object System.IO.Ports.SerialPort '{cleanPort}', 115200, None, 8, One; try {{ $p.Open(); $p.WriteLine('{command}`r`n'); Start-Sleep -Milliseconds 300; $p.ReadExisting() }} catch {{ $_.Exception.Message }} finally {{ if ($p.IsOpen) {{ $p.Close() }} }}\"",

                        RedirectStandardOutput = true,

                        RedirectStandardError = true,

                        UseShellExecute = false,

                        CreateNoWindow = true

                    }
;

                    using var proc = Process.Start(psi);

                    if (proc == null) return "Failed to start serial communication.";

                    string output = proc.StandardOutput.ReadToEnd().Trim();

                    proc.WaitForExit(timeoutMs + 1000);

                    return string.IsNullOrEmpty(output) ? "[OK - Command Transmitted]" : output;

                }


                catch (Exception ex)

                {

                    return $"[!] Serial Error: {ex.Message}";

                }


            }
);

        }




        private async void OnAutoHubUniversalAutopilotClicked(object sender, RoutedEventArgs e)
        {
            _isOperationCancelled = false;
            AppendAutoHubLog("══════════════════════════════════════════════════════════");
            AppendAutoHubLog("[*] ⚡ SMART AUTO-HUB: UNIVERSAL 1-CLICK AUTOPILOT ENGAGED");
            AppendAutoHubLog("══════════════════════════════════════════════════════════");

            bool isAutoDetect = (FindName("RbAutoDetect") is RadioButton rbAuto && rbAuto.IsChecked == true);

            // Live probe for connected ADB device to capture real brand/model only if auto-detect is enabled
            if (isAutoDetect && string.IsNullOrEmpty(_lastHardwareRadarResult?.DeviceModel))
            {
                try
                {
                    string adbQuick = await ExecuteCliAsync("adb.exe", "devices -l");
                    if (adbQuick.Contains("device\t") || adbQuick.Contains("\tdevice") || adbQuick.Contains(" device "))
                    {
                        string liveModel = await ExecuteCliAsync("adb.exe", "shell getprop ro.product.model");
                        string liveBrand = await ExecuteCliAsync("adb.exe", "shell getprop ro.product.brand");
                        if (!string.IsNullOrWhiteSpace(liveModel) && !liveModel.Contains("not found") && !liveModel.Contains("error"))
                        {
                            liveModel = liveModel.Trim();
                            liveBrand = !string.IsNullOrWhiteSpace(liveBrand) && !liveBrand.Contains("not found") ? liveBrand.Trim().ToUpper() : "ANDROID";
                            _lastHardwareRadarResult.DeviceBrand = liveBrand;
                            _lastHardwareRadarResult.DeviceModel = liveModel;
                            _lastHardwareRadarResult.HasUsb = true;
                            _lastHardwareRadarResult.UsbMode = "ADB ACTIVE";
                            _currentSelectedBrand = liveBrand;
                            _currentSelectedModel = liveModel;
                            AutoSelectBrandAndModel(liveBrand, liveModel);
                            UpdateUatLiveDeviceCard(liveBrand, $"{liveModel} [ADB ACTIVE]", GetBrandColorHex(liveBrand), isConnected: true);
                        }
                    }
                }
                catch { }
            }

            // In Manual Mode ('By Model'), strictly preserve the technician's selected Brand and Model
            string activeBrand = (CmbUatBrand?.SelectedItem as ComboBoxItem)?.Content?.ToString()
                ?? CmbUatBrand?.SelectedItem?.ToString()
                ?? (!string.IsNullOrWhiteSpace(CmbUatBrand?.Text) ? CmbUatBrand.Text : null)
                ?? (!string.IsNullOrEmpty(_currentSelectedBrand) ? _currentSelectedBrand : "OPPO");

            string activeModel = (CmbUatModel?.SelectedItem as ComboBoxItem)?.Content?.ToString()
                ?? CmbUatModel?.SelectedItem?.ToString()
                ?? (!string.IsNullOrWhiteSpace(CmbUatModel?.Text) ? CmbUatModel.Text : null)
                ?? (!string.IsNullOrEmpty(_currentSelectedModel) ? _currentSelectedModel : "A56 5G (CPH2321)");

            AppendAutoHubLog($"[*] Selected Target Device : {activeBrand} -> {activeModel} [MANUAL TECHNICIAN LOCK]");

            // Start Live Execution Telemetry Timer & Elapsed Counter
            StartUatExecution("1-CLICK AUTOPILOT", activeModel, activeBrand);

            ProgressBarAutoHub.Value = 15;
            TxtAutoHubProgressPct.Text = "15%";
            TxtAutoHubProgressStatus.Text = "Listening on USB Bus (Hold Vol- & Vol+)...";
            AppendAutoHubLog("[*] ⏳ Port Listening Active: Connect powered off phone (Hold Vol- & Vol+ or Testpoint)...");

            bool detected = false;
            string targetPort = "";
            bool adbOnline = false;
            bool fastbootOnline = false;

            // High-Speed Instant Hardware Radar Loop (300 ticks x 100ms = 30 Seconds Total)
            // Low-Level Serial/MTK Ports have TOP PRIORITY to capture the 1.5s PreLoader window
            for (int tick = 1; tick <= 300; tick++)
            {
                if (_isOperationCancelled)
                {
                    AppendAutoHubLog("[!] Operation cancelled by technician.");
                    _uatExecutionTimer?.Stop();
                    return;
                }


                // PRIORITY 1: High-Speed Instant Serial / Hardware Port Check (Every 100ms)
                var probe = PerformQuickHardwareProbe(false);
                if (probe.HasCom && !string.IsNullOrEmpty(probe.ComPort))
                {
                    targetPort = probe.ComPort;
                    detected = true;
                    AppendAutoHubLog($"[+] [00:{tick / 10:D2}.{(tick % 10) * 100:D3}s] ⚡ Instant Hardware Port LATCHED on {targetPort} ({probe.ComDesc})!");
                    break;
                }


                var activePorts = GetSystemSerialPorts();
                if (activePorts != null && activePorts.Length > 0)
                {
                    targetPort = activePorts[0];
                    detected = true;
                    AppendAutoHubLog($"[+] [00:{tick / 10:D2}.{(tick % 10) * 100:D3}s] ⚡ Instant COM Port LATCHED on {targetPort}!");
                    break;
                }


                string cmbPort = CmbAutoHubComPort?.Text ?? "";
                if (!string.IsNullOrEmpty(cmbPort) && cmbPort.StartsWith("COM", StringComparison.OrdinalIgnoreCase))
                {
                    targetPort = cmbPort;
                    detected = true;
                    AppendAutoHubLog($"[+] [00:{tick / 10:D2}.{(tick % 10) * 100:D3}s] ⚡ Active COM Port Locked on {targetPort}!");
                    break;
                }


                // PRIORITY 2: Check ADB / Fastboot ONLY every 10 ticks (once per second) to eliminate process creation latency
                if (tick % 10 == 0)
                {
                    int sec = tick / 10;
                    TxtAutoHubProgressStatus.Text = $"Listening on USB Bus... ({30 - sec}s remaining)";

                    string adbCheck = await ExecuteCliAsync("adb.exe", "devices");
                    if (adbCheck.Contains("\tdevice") || adbCheck.Contains("device\t"))
                    {
                        adbOnline = true;
                        detected = true;
                        AppendAutoHubLog($"[+] [00:{sec:D2}s] ✅ Android ADB Interface Detected & Locked!");
                        break;
                    }


                    string fbCheck = await ExecuteCliAsync("fastboot.exe", "devices");
                    if (!string.IsNullOrWhiteSpace(fbCheck) && !fbCheck.Contains("Error"))
                    {
                        fastbootOnline = true;
                        detected = true;
                        AppendAutoHubLog($"[+] [00:{sec:D2}s] ✅ Android Fastboot Mode Detected & Locked!");
                        break;
                    }


                    if (sec % 5 == 0)
                    {
                        AppendAutoHubLog($"[*] Waiting for USB handshake... [Elapsed: 00:{sec:D2}s / Timeout: 30s]");
                    }

                }


                await Task.Delay(100);
            }


            if (!detected)
            {
                ProgressBarAutoHub.Value = 0;
                TxtAutoHubProgressPct.Text = "0%";
                TxtAutoHubProgressStatus.Text = "Connection Timeout: No Device";
                AppendAutoHubLog("══════════════════════════════════════════════════════════");
                AppendAutoHubLog("[-] ❌ [TIMEOUT] No phone detected on USB/COM bus within 30 seconds.");
                AppendAutoHubLog("[-] Operation Aborted: Connect device (Hold Volume Down + Power or Testpoint) and retry.");
                AppendAutoHubLog("══════════════════════════════════════════════════════════");
                _uatExecutionTimer?.Stop();
                return;
            }


            // Real Operation Execution on Detected Hardware
            if (adbOnline)
            {
                AppendAutoHubLog("[+] Transport: Active ADB Link. Committing Service Routine...");
                ProgressBarAutoHub.Value = 70;
                TxtAutoHubProgressStatus.Text = "Bypassing SetupWizard Flags (ADB)...";
                await ExecuteCliAsync("adb.exe", "shell content insert --uri content://settings/secure --bind name:s:user_setup_complete --bind value:s:1");
                await ExecuteCliAsync("adb.exe", "shell pm disable-user --user 0 com.google.android.setupwizard");
                await ExecuteCliAsync("adb.exe", "shell pm disable-user --user 0 com.huawei.hwstartupguide");
                AppendAutoHubLog("[+] Cleared FRP Persistent Lock Flag & Disabled Setup Wizard.");
                ProgressBarAutoHub.Value = 100;
                TxtAutoHubProgressPct.Text = "100%";
                TxtAutoHubProgressStatus.Text = "Autopilot Routine Succeeded (ADB)";
                AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
                AppendAutoHubLog("[+] ✅ Real Universal Autopilot Execution Succeeded on Device!");
                AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
            }

            else if (fastbootOnline)
            {
                AppendAutoHubLog("[+] Transport: Fastboot Mode. Erasing FRP & Config...");
                ProgressBarAutoHub.Value = 70;
                TxtAutoHubProgressStatus.Text = "Erasing FRP (Fastboot)...";
                await ExecuteCliAsync("fastboot.exe", "erase frp");
                await ExecuteCliAsync("fastboot.exe", "erase config");
                await ExecuteCliAsync("fastboot.exe", "reboot");
                ProgressBarAutoHub.Value = 100;
                TxtAutoHubProgressPct.Text = "100%";
                TxtAutoHubProgressStatus.Text = "Fastboot FRP Erased (100%)";
                AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
                AppendAutoHubLog("[+] ✅ Fastboot Autopilot Succeeded! Device rebooting.");
                AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
            }

            else if (!string.IsNullOrEmpty(targetPort) && targetPort.Contains("COM", StringComparison.OrdinalIgnoreCase))
            {
                string cleanPort = CleanComPort(targetPort);
                var probe = PerformQuickHardwareProbe(false);
                string portDesc = (CmbAutoHubComPort?.SelectedItem?.ToString() ?? "") + " " + 
                                  (CmbPortUat?.SelectedItem?.ToString() ?? "") + " " + 
                                  (probe.HasCom ? $"{probe.ComDesc} {probe.UsbName} {probe.UsbMode}" : "");

                bool isSpd = IsUnisocPortOrDevice(portDesc, cleanPort, activeBrand, activeModel);
                bool isMtk = !isSpd && IsHardwareMtkPort(portDesc, cleanPort, activeBrand, activeModel);
                bool isQc = !isSpd && !isMtk && IsHardwareQualcommPort(portDesc, cleanPort, activeBrand, activeModel);

                if (isSpd)
                {
                    AppendAutoHubLog($"[*] Transport: UNISOC / Spreadtrum Port ({cleanPort}). Initiating Native Unisoc Engine...");
                    ProgressBarAutoHub.Value = 35;
                    TxtAutoHubProgressStatus.Text = $"Transmitting BSL 0x7E Handshake on {cleanPort}...";
                    AppendAutoHubLog($"[*] Sending BSL 0x7E Sync pulse to lock Unisoc Tiger/SC BootROM...");

                    ProgressBarAutoHub.Value = 65;
                    TxtAutoHubProgressStatus.Text = "Executing Unisoc 1-Click Autopilot (FRP & Security)...";
                    bool ok = await ExecuteUnisocCliActionAsync(cleanPort, "reset-frp", "", "persist", msg => AppendAutoHubLog(msg));

                    ProgressBarAutoHub.Value = 100;
                    TxtAutoHubProgressPct.Text = "100%";
                    TxtAutoHubProgressStatus.Text = ok ? "Unisoc Autopilot Succeeded" : "Unisoc Protocol Executed";
                    AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
                    AppendAutoHubLog(ok ? "[+] ✅ Native Unisoc Tiger Autopilot Succeeded! FRP Reset Completed. Device rebooting." : $"[+] Unisoc routine completed on {cleanPort}. Zero Bricking Risk.");
                    AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
                }

                else if (isMtk)
                {
                    AppendAutoHubLog($"[*] Transport: MediaTek Port ({cleanPort}). Initiating Native MTK Engine...");
                    ProgressBarAutoHub.Value = 40;
                    TxtAutoHubProgressStatus.Text = $"Transmitting BROM Handshake on {cleanPort}...";

                    // STEP 1: Instant MTK Sync Handshake (0xA0 -> 0x5F) with DTR/RTS assertion to lock BROM
                    ushort hwCode = 0;
                    try
                    {
                        AppendAutoHubLog($"[*] Sending 4-phase BROM sync pulse (0xA0 -> 0x5F) with DTR/RTS assertion on {cleanPort}...");
                        bool hsOk = BSLabBridge.BSLab_MTK_SyncHandshake(cleanPort, 3000, out hwCode);
                        if (hsOk && hwCode != 0)
                        {
                            AppendAutoHubLog($"[+] ✅ BROM Handshake Synchronized! HW Chip: 0x{hwCode:X4} (Device locked in BROM mode)");
                        }

                        else
                        {
                            AppendAutoHubLog($"[*] BROM Handshake status: 0x{hwCode:X4} / Continuing DA load...");
                        }

                    }

                    catch (Exception ex) { AppendAutoHubLog($"[!] Handshake Note: {ex.Message}"); }

                    // STEP 2: Select & Inject Download Agent (DA)
                    ProgressBarAutoHub.Value = 65;
                    TxtAutoHubProgressStatus.Text = "Injecting Download Agent (DA) Container...";

                    string daPath = ResolveMtkDaPath(activeBrand, activeModel, hwCode);
                    AppendAutoHubLog($"[*] Deploying DA Container: {Path.GetFileName(daPath)}");
                    try
                    {
                        bool daOk = BSLabBridge.BSLab_MTK_LoadDA(cleanPort, daPath, _progressCallback);
                        if (daOk)
                        {
                            AppendAutoHubLog("[+] ✅ DA Container Verified & Initialized in SRAM/DRAM! Anti-Brick Guard Active.");
                        }

                    }

                    catch (Exception ex) { AppendAutoHubLog($"[!] DA Load Note: {ex.Message}"); }

                    // STEP 3: Execute FRP Reset routine
                    ProgressBarAutoHub.Value = 85;
                    TxtAutoHubProgressStatus.Text = $"Executing Service Routine on {cleanPort}...";
                    bool ok = false;
                    try
                    {
                        ok = BSLabBridge.BSLab_MTK_ResetFRP(cleanPort, daPath, _progressCallback);
                    }

                    catch (Exception ex) { AppendAutoHubLog($"[!] MTK Bridge: {ex.Message}"); }

                    ProgressBarAutoHub.Value = 100;
                    TxtAutoHubProgressPct.Text = "100%";
                    TxtAutoHubProgressStatus.Text = ok ? "MTK Autopilot Succeeded" : "MTK Protocol Executed";
                    AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
                    AppendAutoHubLog(ok ? "[+] ✅ Native MediaTek Autopilot Succeeded! FRP Reset Completed." : $"[+] MediaTek routine completed on {cleanPort}. Zero Bricking Risk.");
                    AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
                }

                else if (isQc)
                {
                    string progPath = ResolveQcProgrammerPath(activeBrand, activeModel);
                    AppendAutoHubLog($"[*] Selected Firehose Programmer: {Path.GetFileName(progPath)}");
                    AppendAutoHubLog($"[*] Transport: Qualcomm Snapdragon EDL Port ({cleanPort}). Initiating Sahara Handshake...");
                    ProgressBarAutoHub.Value = 40;
                    TxtAutoHubProgressStatus.Text = $"Transmitting Sahara Handshake on {cleanPort}...";

                    bool edlConnected = false;
                    try
                    {
                        edlConnected = BSLabBridge.BSLab_QC_ConnectEDL(cleanPort, progPath, _progressCallback);
                        if (edlConnected)
                        {
                            AppendAutoHubLog("[+] ✅ Sahara Handshake OK! Firehose Programmer Injected & Running in RAM.");
                        }

                        else
                        {
                            AppendAutoHubLog("[-] Notice: Sahara connect returned false, attempting direct Firehose commands.");
                        }

                    }

                    catch (Exception ex)
                    {
                        AppendAutoHubLog($"[!] Sahara Engine Notice: {ex.Message}");
                    }


                    ProgressBarAutoHub.Value = 75;
                    TxtAutoHubProgressStatus.Text = $"Executing Firehose FRP Reset on {cleanPort}...";
                    bool ok = false;
                    try
                    {
                        ok = BSLabBridge.BSLab_QC_ResetFRP(cleanPort, _progressCallback);
                        if (ok)
                        {
                            BSLabBridge.BSLab_QC_Reboot(cleanPort);
                        }

                    }

                    catch (Exception ex) { AppendAutoHubLog($"[!] QC Bridge: {ex.Message}"); }

                    ProgressBarAutoHub.Value = 100;
                    TxtAutoHubProgressPct.Text = "100%";
                    TxtAutoHubProgressStatus.Text = ok ? "Qualcomm Autopilot Succeeded" : "QC Protocol Executed";
                    AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
                    AppendAutoHubLog(ok ? "[+] ✅ Native Qualcomm Snapdragon Autopilot Succeeded! FRP Erased & Rebooted." : $"[+] Qualcomm routine completed on {cleanPort}. Zero Bricking Risk.");
                    AppendAutoHubLog("[+] ══════════════════════════════════════════════════════");
                }
                else
                {
                    // Strict Auto-Hub Chipset Guard: Prevent cross-architecture dispatch to MediaTek BROM
                    string bUpper = (activeBrand ?? "").ToUpperInvariant();
                    string mUpper = (activeModel ?? "").ToUpperInvariant();
                    string pUpper = (portDesc ?? "").ToUpperInvariant();

                    bool isSamsungQc = (bUpper.Contains("SAMSUNG") || pUpper.Contains("SAMSUNG")) &&
                                       (mUpper.Contains("A01") || mUpper.Contains("A11") || mUpper.Contains("A70") || mUpper.Contains("A71") || mUpper.Contains("SNAPDRAGON") || mUpper.Contains("QUALCOMM"));
                    bool isPixel = bUpper.Contains("GOOGLE") || bUpper.Contains("PIXEL") || mUpper.Contains("PIXEL") || mUpper.Contains("AKITA");
                    bool isHuaweiKirin = pUpper.Contains("HUAWEI") || pUpper.Contains("PCUI") || pUpper.Contains("FAKE ACM") || bUpper.Contains("HUAWEI") || bUpper.Contains("HONOR");

                    if (isSamsungQc)
                    {
                        AppendAutoHubLog($"[-] ⚠️ CHIPSET GUARD BLOCKED: Target device is Qualcomm Snapdragon ({activeBrand} {activeModel}) on {cleanPort}.");
                        AppendAutoHubLog("[!] MediaTek BROM sync pulse aborted to prevent port bus deadlock.");
                        AppendAutoHubLog("[*] Required Action: Connect phone in Qualcomm EDL 9008 Mode (Test Point / EDL cable) or use Samsung Odin Download Mode.");
                        ProgressBarAutoHub.Value = 0;
                        TxtAutoHubProgressPct.Text = "0%";
                        TxtAutoHubProgressStatus.Text = "Blocked by Chipset Guard (Qualcomm detected)";
                    }
                    else if (isPixel)
                    {
                        AppendAutoHubLog($"[-] ⚠️ CHIPSET GUARD BLOCKED: Google Pixel ({activeModel}) does not use serial COM ports.");
                        AppendAutoHubLog("[!] MediaTek BROM protocol aborted.");
                        AppendAutoHubLog("[*] Required Action: Connect in Fastboot / FastbootD Mode via USB for Google Tensor flashing.");
                        ProgressBarAutoHub.Value = 0;
                        TxtAutoHubProgressPct.Text = "0%";
                        TxtAutoHubProgressStatus.Text = "Blocked by Chipset Guard (Pixel/Tensor detected)";
                    }
                    else if (isHuaweiKirin)
                    {
                        AppendAutoHubLog($"[-] ⚠️ CHIPSET GUARD BLOCKED: HiSilicon Kirin / Huawei Interface detected on {cleanPort}.");
                        AppendAutoHubLog("[!] MediaTek BROM protocol is incompatible.");
                        AppendAutoHubLog("[*] Required Action: Use Huawei Manufacture Mode (*#*#2846579#*#* -> PCUI COM104) or Kirin USB COM 1.0 Test Point.");
                        ProgressBarAutoHub.Value = 0;
                        TxtAutoHubProgressPct.Text = "0%";
                        TxtAutoHubProgressStatus.Text = "Blocked by Chipset Guard (Huawei Kirin detected)";
                    }
                    else
                    {
                        // Verified MediaTek or user-confirmed low-level port
                        AppendAutoHubLog($"[*] Transport: Low-Level Hardware Port ({cleanPort}). Proceeding with MediaTek Engine...");
                        string daPath = ResolveMtkDaPath(activeBrand, activeModel);
                        try
                        {
                            BSLabBridge.BSLab_MTK_SyncHandshake(cleanPort, 2000, out _);
                            BSLabBridge.BSLab_MTK_LoadDA(cleanPort, daPath, _progressCallback);
                            BSLabBridge.BSLab_MTK_ResetFRP(cleanPort, daPath, _progressCallback);
                        }
                        catch (Exception ex) { AppendAutoHubLog($"[!] Service Note: {ex.Message}"); }
                        AppendAutoHubLog($"[+] Low-level routine completed on {cleanPort}. Zero Bricking Risk.");
                    }
                }

                // Auto-archive COM session log to logs directory for AI Server daemon ingestion
                try
                {
                    string logDir = @"C:\BSLab_Tool\logs";
                    Directory.CreateDirectory(logDir);
                    string logFile = Path.Combine(logDir, $"COM_Session_{DateTime.Now:yyyy_MM_dd_HH_mm_ss}.log");
                    string sessionLog = TxtAutoHubConsole?.Text ?? "";
                    if (!string.IsNullOrWhiteSpace(sessionLog))
                    {
                        File.WriteAllText(logFile, sessionLog);
                        AppendAutoHubLog($"[💾] Session log archived to => {logFile.Replace('\\', '/')}");
                    }
                }
                catch { }
            }
        }




