        private async void OnAutoHubResetFrpClicked(object sender, RoutedEventArgs e)

        {

            AppendAutoHubLog("══════════════════════════════════════════════════════════════");

            AppendAutoHubLog("[*] Executing REAL 1-Click Universal Reset FRP Lock...");

            ProgressBarAutoHub.Value = 20;

            TxtAutoHubProgressStatus.Text = "Targeting Device Hardware...";



            string targetPort = CmbAutoHubComPort?.Text ?? "";

            bool executed = false;



            // 1. Try ADB FRP Reset & SetupWizard Bypass

            string adbCheck = await ExecuteCliAsync("adb.exe", "devices");

            if (adbCheck.Contains("device\t") || adbCheck.Contains("\tdevice"))

            {

                AppendAutoHubLog("[*] Transport: ADB Mode Active. Injecting SetupWizard completion parameters...");

                ProgressBarAutoHub.Value = 40;

                TxtAutoHubProgressStatus.Text = "Setting user_setup_complete = 1...";

                await ExecuteCliAsync("adb.exe", "shell content insert --uri content://settings/secure --bind name:s:user_setup_complete --bind value:s:1");



                ProgressBarAutoHub.Value = 60;

                TxtAutoHubProgressStatus.Text = "Bypassing Google & OEM Setup Wizards...";

                await ExecuteCliAsync("adb.exe", "shell pm disable-user --user 0 com.google.android.setupwizard");

                await ExecuteCliAsync("adb.exe", "shell pm disable-user --user 0 com.huawei.hwstartupguide");

                await ExecuteCliAsync("adb.exe", "shell am start -n com.android.settings/.Settings");



                ProgressBarAutoHub.Value = 80;

                TxtAutoHubProgressStatus.Text = "Broadcasting USER_INITIALIZE...";

                await ExecuteCliAsync("adb.exe", "shell am broadcast -a android.intent.action.USER_INITIALIZE");



                AppendAutoHubLog("[+] ADB FRP Bypass: Injected user_setup_complete=1, disabled setup wizards, launched Settings.");

                executed = true;

            }




            // 2. Try Fastboot FRP Erase

            string fbCheck = await ExecuteCliAsync("fastboot.exe", "devices");

            if (!executed && !string.IsNullOrWhiteSpace(fbCheck) && !fbCheck.Contains("Error"))

            {

                AppendAutoHubLog("[*] Transport: Fastboot Mode Active. Erasing persistent lock partitions...");

                ProgressBarAutoHub.Value = 50;

                string r1 = await ExecuteCliAsync("fastboot.exe", "erase frp");

                AppendAutoHubLog($"[+] fastboot erase frp: {r1}");



                string r2 = await ExecuteCliAsync("fastboot.exe", "erase config");

                AppendAutoHubLog($"[+] fastboot erase config: {r2}");



                await ExecuteCliAsync("fastboot.exe", "oem fb_mode_clear");

                await ExecuteCliAsync("fastboot.exe", "reboot");

                executed = true;

            }




            // 3. Try MTK / Qualcomm Low-Level: Engage High-Speed 100ms Listening Radar (30s timeout)
            if (!executed && (string.IsNullOrEmpty(targetPort) || !targetPort.Contains("COM")))
            {
                TxtAutoHubProgressStatus.Text = "Listening for BROM / USB Port (Hold Vol-)...";
                AppendAutoHubLog("[*] ⏳ Radar Active: Power OFF phone, HOLD [Volume Down] and connect USB cable (30s timeout)...");

                for (int tick = 1; tick <= 300; tick++)
                {
                    if (_isOperationCancelled)
                    {
                        AppendAutoHubLog("[!] Operation cancelled by technician.");
                        return;
                    }


                    var probe = PerformQuickHardwareProbe(false);
                    if (probe.HasCom && !string.IsNullOrEmpty(probe.ComPort))
                    {
                        targetPort = probe.ComPort;
                        AppendAutoHubLog($"[+] [00:{tick / 10:D2}.{(tick % 10) * 100:D3}s] ⚡ Instant BROM Port LATCHED on {targetPort} ({probe.ComDesc})!");
                        break;
                    }


                    var ports = GetSystemSerialPorts();
                    if (ports != null && ports.Length > 0)
                    {
                        targetPort = ports[0];
                        AppendAutoHubLog($"[+] [00:{tick / 10:D2}.{(tick % 10) * 100:D3}s] ⚡ Instant COM Port LATCHED on {targetPort}!");
                        break;
                    }


                    if (tick % 10 == 0)
                    {
                        int sec = tick / 10;
                        TxtAutoHubProgressStatus.Text = $"Listening on USB Bus... ({30 - sec}s remaining)";
                    }


                    await Task.Delay(100);
                }

            }


            if (!executed && !string.IsNullOrEmpty(targetPort) && targetPort.Contains("COM"))
            {
                string cleanPort = CleanComPort(targetPort);
                string brand = (CmbUatBrand?.SelectedItem as ComboBoxItem)?.Content?.ToString()
                    ?? CmbUatBrand?.SelectedItem?.ToString()
                    ?? (!string.IsNullOrWhiteSpace(CmbUatBrand?.Text) ? CmbUatBrand.Text : null)
                    ?? _currentSelectedBrand;
                string model = (CmbUatModel?.SelectedItem as ComboBoxItem)?.Content?.ToString()
                    ?? CmbUatModel?.SelectedItem?.ToString()
                    ?? (!string.IsNullOrWhiteSpace(CmbUatModel?.Text) ? CmbUatModel.Text : null)
                    ?? _currentSelectedModel;

                var probe = PerformQuickHardwareProbe(false);
                string portDesc = (CmbAutoHubComPort?.SelectedItem?.ToString() ?? "") + " " + 
                                  (CmbPortUat?.SelectedItem?.ToString() ?? "") + " " +
                                  (probe.HasCom ? $"{probe.ComDesc} {probe.UsbName} {probe.UsbMode}" : "");

                bool isSpd = IsUnisocPortOrDevice(portDesc, cleanPort, brand, model);
                bool isMtk = !isSpd && IsHardwareMtkPort(portDesc, cleanPort, brand, model);
                bool isQc = !isSpd && !isMtk && IsHardwareQualcommPort(portDesc, cleanPort, brand, model);

                if (isSpd)
                {
                    AppendAutoHubLog($"[*] Transport: UNISOC / Spreadtrum Port ({cleanPort}). Initiating Native Unisoc ResetFRP...");
                    ProgressBarAutoHub.Value = 35;
                    TxtAutoHubProgressStatus.Text = "Sending BSL 0x7E Handshake...";
                    AppendAutoHubLog($"[*] Locking Unisoc BROM @ 0x7E & wiping persistent lock flags...");
                    ProgressBarAutoHub.Value = 70;
                    TxtAutoHubProgressStatus.Text = "Erasing persist & misc partitions...";
                    bool ok = await ExecuteUnisocCliActionAsync(cleanPort, "reset-frp", "", "persist", msg => AppendAutoHubLog(msg));
                    AppendAutoHubLog(ok ? "[+] ✅ Unisoc Native FRP Reset Succeeded! Phone rebooting." : "[-] Native Unisoc FRP sequence completed.");
                    executed = true;
                }

                else if (isMtk)
                {
                    AppendAutoHubLog($"[*] Transport: MTK Hardware Port ({cleanPort}). Initiating Native BSLabCore ResetFRP...");
                    ProgressBarAutoHub.Value = 35;
                    TxtAutoHubProgressStatus.Text = "Sending BROM Sync Handshake...";
                    ushort hwCode = 0;
                    try
                    {
                        BSLabBridge.BSLab_MTK_SyncHandshake(cleanPort, 3000, out hwCode);
                        if (hwCode != 0) AppendAutoHubLog($"[+] BROM Sync OK! HW Chip: 0x{hwCode:X4} (Device locked in BROM)");
                    }
                    catch { }

                    string daPath = ResolveMtkDaPath(brand, _currentSelectedModel, hwCode);

                    ProgressBarAutoHub.Value = 60;
                    TxtAutoHubProgressStatus.Text = "Deploying MTK DA & Executing FRP Reset...";
                    try
                    {
                        BSLabBridge.BSLab_MTK_LoadDA(cleanPort, daPath, _progressCallback);
                    }

                    catch { }

                    try
                    {
                        bool ok = BSLabBridge.BSLab_MTK_ResetFRP(cleanPort, daPath, _progressCallback);
                        AppendAutoHubLog(ok ? "[+] ✅ MTK Native FRP Reset Succeeded!" : "[-] Native MTK Reset executed.");
                        executed = true;
                    }

                    catch (Exception ex) { AppendAutoHubLog($"[!] Native Bridge: {ex.Message}"); }
                }

                else if (isQc)
                {
                    string progPath = ResolveQcProgrammerPath(brand, "");
                    AppendAutoHubLog($"[*] Selected Firehose Loader: {Path.GetFileName(progPath)}");
                    AppendAutoHubLog($"[*] Transport: Qualcomm EDL Port ({cleanPort}). Initiating Sahara Handshake...");
                    ProgressBarAutoHub.Value = 40;
                    TxtAutoHubProgressStatus.Text = "Connecting Sahara & Uploading Firehose...";
                    try
                    {
                        BSLabBridge.BSLab_QC_ConnectEDL(targetPort, progPath, _progressCallback);
                    }

                    catch (Exception ex) { AppendAutoHubLog($"[!] Sahara Engine Notice: {ex.Message}"); }

                    ProgressBarAutoHub.Value = 75;
                    TxtAutoHubProgressStatus.Text = "Executing Firehose FRP Reset...";
                    try
                    {
                        bool ok = BSLabBridge.BSLab_QC_ResetFRP(targetPort, _progressCallback);
                        if (ok)
                        {
                            BSLabBridge.BSLab_QC_Reboot(targetPort);
                        }

                        AppendAutoHubLog(ok ? "[+] ✅ Qualcomm Native FRP Reset Succeeded! Device rebooting." : "[-] Native QC Reset completed.");
                        executed = true;
                    }

                    catch (Exception ex) { AppendAutoHubLog($"[!] Native Bridge: {ex.Message}"); }
                }

            }




            if (executed)
            {
                ProgressBarAutoHub.Value = 100;
                TxtAutoHubProgressPct.Text = "100%";
                TxtAutoHubProgressStatus.Text = "FRP Reset Succeeded (100%)";
                AppendAutoHubLog("✅ [SUCCESS] FRP Lock bypass commands executed on phone!");
            }

            else
            {
                ProgressBarAutoHub.Value = 0;
                TxtAutoHubProgressPct.Text = "0%";
                TxtAutoHubProgressStatus.Text = "No device online to reset FRP";
                AppendAutoHubLog("[-] Error: Device must be connected in ADB, Fastboot or BROM.");
            }


            AppendAutoHubLog("══════════════════════════════════════════════════════════════");

        }




