                    try
                    {
                        bool ok = BSLabBridge.BSLab_QC_FactoryReset(cleanPort, true, _progressCallback);
                        if (ok)
                        {
                            BSLabBridge.BSLab_QC_Reboot(cleanPort);
                        }

                        AppendAutoHubLog(ok ? "[+] ✅ [SUCCESS] Qualcomm Snapdragon Factory Reset Completed! Userdata & Metadata erased." : "[-] Low-level factory reset sequence completed.");
                        executed = true;
                    }
                    catch (Exception ex)
                    {
                        AppendAutoHubLog($"[!] Factory Reset Engine: {ex.Message}");
                    }
                }
            }


            if (executed)
            {
                ProgressBarAutoHub.Value = 100;
                TxtAutoHubProgressPct.Text = "100%";
                TxtAutoHubProgressStatus.Text = "Factory Reset Dispatched";
                AppendAutoHubLog("✅ [SUCCESS] Factory reset sequence sent to device.");
            }

            else
            {
                ProgressBarAutoHub.Value = 0;
                TxtAutoHubProgressPct.Text = "0%";
                TxtAutoHubProgressStatus.Text = "No device online";
                AppendAutoHubLog("[-] Error: No phone connected in ADB, Fastboot or COM Port.");
            }


            AppendAutoHubLog("══════════════════════════════════════════════════════════════");

        }




