        private async void OnAutoHubEraseSelectedClicked(object sender, RoutedEventArgs e)
        {
            var selected = GetSelectedPartitionsFromGrid(GridAutoHubPartitions);
            if (selected.Count == 0)
            {
                AppendAutoHubLog("[-] Warning: No partitions selected in table to erase. Select rows first.");
                return;
            }


            var confirm = MessageBox.Show(
                $"WARNING: You are about to erase {selected.Count} partition(s)!\n\nPartitions: {string.Join(", ", selected.Select(p => p.Name))}\n\nAre you absolutely sure?",
                "Auto-Hub Partition Erase Confirmation",
                MessageBoxButton.YesNo,
                MessageBoxImage.Warning);

            if (confirm != MessageBoxResult.Yes)
            {
                AppendAutoHubLog("[*] Partition Erase cancelled safely by technician.");
                return;
            }


            AppendAutoHubLog("══════════════════════════════════════════════════════════════");
            AppendAutoHubLog($"[!] ⚠️ INITIATING PARTITION ERASE ROUTINE: {selected.Count} Partitions");
            AppendAutoHubLog("══════════════════════════════════════════════════════════════");

            string fbCheck = await ExecuteCliAsync("fastboot.exe", "devices");
            bool fbOnline = !string.IsNullOrWhiteSpace(fbCheck) && !fbCheck.Contains("Error");

            int done = 0;
            foreach (var part in selected)
            {
                // Native Partition Doctor Zero-Loss Firewall Guard
                if (BSLabBridge.BSLab_PartitionDoctor_IsProtected(part.Name))
                {
                    AppendAutoHubLog($"[!] 🛡️ FIREWALL BLOCKED: Partition '{part.Name}' contains critical IMEI/Security/UserData! Erase rejected to prevent bricking.");
                    continue;
                }

                done++;
                AppendAutoHubLog($"[*] Erasing partition [{done}/{selected.Count}]: '{part.Name}'...");
                if (fbOnline)
                {
                    string res = await ExecuteCliAsync("fastboot.exe", $"erase {part.Name}");
                    AppendAutoHubLog($"[+] Fastboot: {res}");
                }

                else
                {
                    await ExecuteCliAsync("adb.exe", $"shell su -c dd if=/dev/zero of=/dev/block/by-name/{part.Name} bs=4096 count=256");
                    AppendAutoHubLog($"[+] Zeroed block header for partition: '{part.Name}'");
                }

            }


            AppendAutoHubLog("[+] ✅ Selected partition erase completed successfully.");
            AppendAutoHubLog("══════════════════════════════════════════════════════════════");
        }


        private async void OnAutoHubWriteSelectedClicked(object sender, RoutedEventArgs e)
        {
            var selected = GetSelectedPartitionsFromGrid(GridAutoHubPartitions);
            if (selected.Count == 0)
            {
                AppendAutoHubLog("[-] Warning: No partitions selected in table to write. Select or check a row first.");
                MessageBox.Show("Please select or check a partition row to write/flash an image file.", "Write Partition", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            var targetPart = selected[0];
            var dlg = new OpenFileDialog
            {
                Filter = $"Partition Image (*.img;*.bin)|*.img;*.bin|Raw Binary (*.bin)|*.bin|All Files (*.*)|*.*",
                Title = $"Select Image File to Flash into '{targetPart.Name}' (LBA: 0x{targetPart.StartLba:X8})"
            };

            if (dlg.ShowDialog() != true) return;
            string filePath = dlg.FileName;
            var fi = new FileInfo(filePath);

            // Pre-Flash Verification via native C++ Partition Doctor
            var outErr = new System.Text.StringBuilder(512);
            bool verified = BSLabBridge.BSLab_PartitionDoctor_VerifyImageBeforeFlash(targetPart.Name, filePath, outErr, outErr.Capacity);
            if (!verified)
            {
                string errMsg = outErr.ToString();
                AppendAutoHubLog($"[!] ❌ PARTITION DOCTOR SAFETY ALERT: {errMsg}");
                var warnResult = MessageBox.Show(
                    $"Partition Doctor Pre-Flash Safety Firewall Alert:\n\n{errMsg}\n\n" +
                    "Flashing mismatched binary formats (e.g. DTBO into BOOT) can permanently brick the device!\n\n" +
                    "Do you still want to force override and flash anyway?",
                    "Pre-Flash Verification Warning",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Error);

                if (warnResult != MessageBoxResult.Yes)
                {
                    AppendAutoHubLog("[*] Write aborted safely by technician following Partition Doctor firewall alert.");
                    return;
                }
                AppendAutoHubLog("[!] ⚠️ MANUAL OVERRIDE: Proceeding with write despite format mismatch warning.");
            }
            else
            {
                AppendAutoHubLog($"[+] 🛡️ Partition Doctor verified: Image format matches target partition '{targetPart.Name}'.");
            }

            var confirm = MessageBox.Show(
                $"Are you sure you want to FLASH image:\n{Path.GetFileName(filePath)} ({fi.Length / (1024.0 * 1024.0):F2} MB)\n\n" +
                $"INTO TARGET PARTITION: '{targetPart.Name}' (Size: {targetPart.SizeStr})?\n\n" +
                $"CAUTION: Existing sectors on '{targetPart.Name}' will be overwritten with new data!",
                "Confirm Single Partition Write",
                MessageBoxButton.YesNo,
                MessageBoxImage.Warning
            );

            if (confirm != MessageBoxResult.Yes)
            {
                AppendAutoHubLog("[*] Partition write cancelled safely by technician.");
                return;
            }

            AppendAutoHubLog("══════════════════════════════════════════════════════════════");
            AppendAutoHubLog($"[*] ✍️ FLASHING TARGET PARTITION: '{targetPart.Name}'");
            AppendAutoHubLog($"[*] Source Image: {filePath}");
            AppendAutoHubLog($"[*] Sector Offset: LBA 0x{targetPart.StartLba:X8} (Sectors: {targetPart.SectorCount})");
            AppendAutoHubLog("══════════════════════════════════════════════════════════════");

            ProgressBarAutoHub.Value = 20;
            TxtAutoHubProgressStatus.Text = $"Writing {targetPart.Name}...";

            string fbCheck = await ExecuteCliAsync("fastboot.exe", "devices");
            bool fbOnline = !string.IsNullOrWhiteSpace(fbCheck) && !fbCheck.Contains("Error");

            if (fbOnline)
            {
                AppendAutoHubLog($"[*] Transport: Fastboot Bootloader. Flashing partition '{targetPart.Name}'...");
                ProgressBarAutoHub.Value = 50;
                string res = await ExecuteCliAsync("fastboot.exe", $"flash {targetPart.Name} \"{filePath}\"");
                AppendAutoHubLog($"[+] Fastboot Output: {res}");
                ProgressBarAutoHub.Value = 100;
                TxtAutoHubProgressStatus.Text = $"Partition '{targetPart.Name}' Flashed Successfully!";
                AppendAutoHubLog($"[+] ✅ Partition '{targetPart.Name}' flashed successfully via Fastboot!");
            }
            else
            {
                string adbCheck = await ExecuteCliAsync("adb.exe", "devices");
                if (adbCheck.Contains("device\t") || adbCheck.Contains("\tdevice"))
                {
                    AppendAutoHubLog($"[*] Transport: ADB Shell. Streaming block device for '{targetPart.Name}'...");
                    ProgressBarAutoHub.Value = 40;
                    await ExecuteCliAsync("adb.exe", $"push \"{filePath}\" /data/local/tmp/{targetPart.Name}.img");
                    ProgressBarAutoHub.Value = 75;
                    string ddRes = await ExecuteCliAsync("adb.exe", $"shell su -c dd if=/data/local/tmp/{targetPart.Name}.img of=/dev/block/by-name/{targetPart.Name} bs=4096");
                    await ExecuteCliAsync("adb.exe", $"shell rm /data/local/tmp/{targetPart.Name}.img");
                    AppendAutoHubLog($"[+] Block Stream Result: {ddRes}");
                    ProgressBarAutoHub.Value = 100;
                    TxtAutoHubProgressStatus.Text = $"Partition '{targetPart.Name}' Written Successfully!";
                    AppendAutoHubLog($"[+] ✅ Partition '{targetPart.Name}' written and synced successfully via ADB!");
                }
                else
                {
                    string targetPort = CleanComPort(CmbAutoHubComPort?.Text ?? "");
                    if (!string.IsNullOrEmpty(targetPort))
                    {
                        AppendAutoHubLog($"[*] Transport: Direct Hardware Bridge ({targetPort}). Streaming binary to LBA 0x{targetPart.StartLba:X8}...");
                        ProgressBarAutoHub.Value = 50;
                        bool ok = false;
                        await Task.Run(() =>
                        {
                            try
                            {
                                ok = BSLabBridge.BSLab_MTK_FlashPartition(targetPort, targetPart.Name, targetPart.StartLba, filePath, _progressCallback);
                            }
                            catch { }
                        });
                        if (ok)
                        {
                            ProgressBarAutoHub.Value = 100;
                            TxtAutoHubProgressStatus.Text = $"Partition '{targetPart.Name}' Flashed via BROM!";
                            AppendAutoHubLog($"[+] ✅ Hardware Bridge: Partition '{targetPart.Name}' successfully written to physical flash!");
                        }
                        else
                        {
                            AppendAutoHubLog($"[-] Hardware flash failed on port {targetPort}. Check connection.");
                        }
                    }
                    else
                    {
                        AppendAutoHubLog("[-] No active transport (Fastboot, ADB, or COM) connected. Connect device and retry.");
                    }
                }
            }
            ProgressBarAutoHub.Value = 0;
        }


        private void UpdateAutoHubPartCount()
        {
            if (TxtAutoHubPartCount != null)
            {
                int total = _autoHubPartitions.Count;
                int selected = _autoHubPartitions.Count(p => p.IsChecked);
                TxtAutoHubPartCount.Text = $" ({selected}/{total} Selected)";
            }
            if (EmptyGptOverlay != null)
            {
                EmptyGptOverlay.Visibility = (_autoHubPartitions.Count == 0) ? Visibility.Visible : Visibility.Collapsed;
            }
        }


        private void OnAutoHubPartitionSearchTextChanged(object sender, TextChangedEventArgs e)
        {
            if (GridAutoHubPartitions == null || _autoHubPartitions == null) return;
            string q = TxtAutoHubPartSearch?.Text?.Trim().ToLowerInvariant() ?? "";
            if (string.IsNullOrEmpty(q))
            {
                GridAutoHubPartitions.ItemsSource = null;
                GridAutoHubPartitions.ItemsSource = _autoHubPartitions;
            }
            else
            {
                var filtered = _autoHubPartitions.Where(p => 
                    p.Name.ToLowerInvariant().Contains(q) || 
                    (p.Filesystem != null && p.Filesystem.ToLowerInvariant().Contains(q)) ||
                    (p.Status != null && p.Status.ToLowerInvariant().Contains(q))
                ).ToList();
                GridAutoHubPartitions.ItemsSource = null;
                GridAutoHubPartitions.ItemsSource = filtered;
            }
            UpdateAutoHubPartCount();
        }


