                Filter = "All Supported Firmware (*.txt;*.ofp;*.ops;*.ozip;*.app;*.pac;*.xml;*.img;*.bin;*.zip;*.tar)|*.txt;*.ofp;*.ops;*.ozip;*.app;*.pac;*.xml;*.img;*.bin;*.zip;*.tar|" +
                         "MediaTek Scatter (*scatter*.txt)|*scatter*.txt|" +
                         "Oppo / Realme OFP (*.ofp)|*.ofp|" +
                         "OnePlus OPS (*.ops)|*.ops|" +
                         "Oppo OZIP (*.ozip)|*.ozip|" +
                         "Huawei UPDATE.APP (*.app)|*.app|" +
                         "Unisoc / SPD PAC (*.pac)|*.pac|" +
                         "Qualcomm Rawprogram XML (*rawprogram*.xml)|*rawprogram*.xml|" +
                         "Raw Partition Image (*.img;*.bin)|*.img;*.bin|" +
                         "All Files (*.*)|*.*"
