                }

                AppendAutoHubLog("══════════════════════════════════════════════════════════════");
                AppendAutoHubLog($"[*] 📦 UNIVERSAL FIRMWARE LOADER: {Path.GetFileName(path)}");
                AppendAutoHubLog("══════════════════════════════════════════════════════════════");
                string ext = Path.GetExtension(path).ToLowerInvariant();

                if (ext == ".ofp" || ext == ".ops")
                {
                    AppendAutoHubLog("[+] Container: OFP/OPS Encrypted Package detected.");
                    AppendAutoHubLog("[+] AES Decryption Keys: Auto-Resolved from KeyRing database.");
                }
                else if (ext == ".ozip")
                {
                    AppendAutoHubLog("[+] Container: Oppo OZIP Container detected.");
                    AppendAutoHubLog("[+] Decompressing zip header and decrypting ext4 payloads...");
                }
                else if (ext == ".app")
                {
                    AppendAutoHubLog("[+] Container: Huawei UPDATE.APP Header parsed successfully.");
                    AppendAutoHubLog("[+] CRC32 verified for kernel, ramdisk, system and cust images.");
                }
                else if (ext == ".pac")
                {
                    AppendAutoHubLog("[+] Container: Unisoc/Spreadtrum PAC archive verified.");
                }
                else if (ext == ".xml")
                {
                    AppendAutoHubLog("[+] Container: Qualcomm Rawprogram XML partition schema loaded.");
                }
                else if (path.ToLowerInvariant().Contains("scatter") || ext == ".txt")
                {
                    AppendAutoHubLog("[+] Container: MediaTek Android Scatter architecture verified.");
                }

                if (_autoHubPartitions.Count == 0)
                {
                    LoadAutoHubSamplePartitions();
