                }

                if (GridAutoHubPartitions != null)
                {
                    GridAutoHubPartitions.ItemsSource = null;
                    GridAutoHubPartitions.ItemsSource = _autoHubPartitions;
                }

                UpdateAutoHubPartCount();
                AppendAutoHubLog($"[+] Flasher Engine: Synchronized {_autoHubPartitions.Count} partitions for flashing.");
            }
        }

