        private async void OnStartUatFlashClicked(object sender, RoutedEventArgs e)
        {
            string fwPath = TxtUatFirmwarePath?.Text?.Trim() ?? "";
            if (string.IsNullOrEmpty(fwPath))
            {
                MessageBox.Show("Please select a firmware file first.", "No Firmware", MessageBoxButton.OK, MessageBoxImage.Warning);
                return;
            }

            var selected = _autoHubPartitions.Where(p => p.IsChecked).ToList();
            if (selected.Count == 0)
            {
                MessageBox.Show("Please check at least one partition in the table to flash.", "No Partitions Selected", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            // Safe Flash filter: Protect preloader / bootloader unless explicitly unchecked
            if (ChkUatSkipPreloader?.IsChecked == true)
            {
                var bootloaders = selected.Where(p => p.Name.Equals("preloader", StringComparison.OrdinalIgnoreCase) ||
                                                      p.Name.Equals("bootloader", StringComparison.OrdinalIgnoreCase) ||
                                                      p.Name.Equals("xbl", StringComparison.OrdinalIgnoreCase) ||
                                                      p.Name.Equals("xbl_config", StringComparison.OrdinalIgnoreCase)).ToList();
                if (bootloaders.Count > 0)
                {
                    foreach (var bl in bootloaders)
                    {
                        selected.Remove(bl);
                    }
                    AppendAutoHubLog("[🛡️ SAFE FLASH] Automatically bypassed preloader/bootloader partitions to protect boot hardware.");
                }
            }

            if (selected.Count == 0)
            {
                MessageBox.Show("All selected partitions were protected bootloaders. To flash them, uncheck '🛡️ Safe Flash'.", "Safe Flash Active", MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            _abortUatFlashRequested = false;
            _isManualSnifferActive = true; // Suspend background polling radar to prevent COM port contention & driver BSOD
            if (BtnUatFlashAbort != null) BtnUatFlashAbort.IsEnabled = true;
            if (BtnUatFlashStart != null) BtnUatFlashStart.IsEnabled = false;

            try
            {
                if (TxtUatFlasherProgressStatus != null) TxtUatFlasherProgressStatus.Text = "● SCANNING | Listening for hardware on USB serial bus...";
                if (ProgressBarUatFlasher != null) ProgressBarUatFlasher.Value = 10;
                if (TxtUatFlasherProgressPercent != null) TxtUatFlasherProgressPercent.Text = "10%";

                var (portOk, port) = await EnsureValidHardwarePortAsync(TxtPort?.Text);
                if (!portOk)
                {
                    AppendAutoHubLog("[-] Hardware Port offline. Please connect device in BROM or EDL mode.");
                    if (TxtUatFlasherProgressStatus != null) TxtUatFlasherProgressStatus.Text = "❌ Device Disconnected: Connect phone in BROM mode (Hold Vol- / Vol+)";
                    if (ProgressBarUatFlasher != null) ProgressBarUatFlasher.Value = 0;
                    if (TxtUatFlasherProgressPercent != null) TxtUatFlasherProgressPercent.Text = "0%";
                    return;
                }

                AppendAutoHubLog("══════════════════════════════════════════════════════════════");
                AppendAutoHubLog($"[*] ⚡ STARTING HIGH-SPEED FIRMWARE FLASH: {Path.GetFileName(fwPath)}");
                AppendAutoHubLog($"[*] Target Port: {port} | Partitions Selected: {selected.Count}");
                AppendAutoHubLog("══════════════════════════════════════════════════════════════");

                // Auto Backup Security partitions in background thread (never blocking UI thread)
                if (ChkUatBackupSecBeforeFlash?.IsChecked == true)
                {
                    AppendAutoHubLog("[*] [PRE-FLASH AUTO-BACKUP] Creating emergency security snapshot (NVRAM/NVDATA/QCN)...");
                    if (TxtUatFlasherProgressStatus != null) TxtUatFlasherProgressStatus.Text = "Creating emergency security snapshot...";
                    await Task.Run(() =>
                    {
                        try
                        {
                            string backupFolder = @"c:\BSLab_Tool\backups\security_nv";
                            Directory.CreateDirectory(backupFolder);
                            BSLabBridge.BSLab_MTK_BackupNVRAM(port, backupFolder, _progressCallback);
                            Dispatcher.Invoke(() => AppendAutoHubLog("[+] [PRE-FLASH AUTO-BACKUP] Security snapshot saved to c:\\BSLab_Tool\\backups\\security_nv"));
                        }
                        catch (Exception bkpEx)
                        {
                            Dispatcher.Invoke(() => AppendAutoHubLog($"[!] Backup notice: {bkpEx.Message}"));
                        }
                    });
                }

                string actualScatterFile = fwPath;
                string ext = Path.GetExtension(fwPath).ToLowerInvariant();
                if (ext == ".ofp" || ext == ".ops" || ext == ".ozip")
                {
                    AppendAutoHubLog($"[*] 🔐 Phase 4 Encrypted Container detected: {ext.ToUpperInvariant()}. Deploying On-The-Fly Decryptor...");
                    if (TxtUatFlasherProgressStatus != null) TxtUatFlasherProgressStatus.Text = "Auto-Decrypting Container...";
                    string unpackOutDir = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "workspace", "extracted_" + Path.GetFileNameWithoutExtension(fwPath));
                    Directory.CreateDirectory(unpackOutDir);
                    string unpackerPy = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "engines", "unpackers", "ofp_ops_unpacker.py");
                    if (File.Exists(unpackerPy))
                    {
                        try
                        {
                            var psi = new ProcessStartInfo("python", $"\"{unpackerPy}\" --input \"{fwPath}\" --out \"{unpackOutDir}\"")
                            {
                                RedirectStandardOutput = true,
                                UseShellExecute = false,
                                CreateNoWindow = true
                            };
                            using var proc = Process.Start(psi);
                            if (proc != null)
                            {
                                proc.WaitForExit(45000);
                                var scatters = Directory.GetFiles(unpackOutDir, "*scatter*.txt", SearchOption.AllDirectories);
                                if (scatters.Length > 0)
                                {
                                    actualScatterFile = scatters[0];
                                    AppendAutoHubLog($"[+] ✅ Successfully Decrypted Container! Scatter located: {Path.GetFileName(actualScatterFile)}");
                                }
                            }
                        }
                        catch (Exception unpackEx)
                        {
                            AppendAutoHubLog($"[!] Auto-decrypt notice: {unpackEx.Message}. Proceeding with container target...");
                        }
                    }
                }

                string daPath = ResolveDaPath(TxtDaPath?.Text);
                AppendAutoHubLog($"[*] Selected DA Loader: {Path.GetFileName(daPath)}");
                if (TxtUatFlasherProgressStatus != null) TxtUatFlasherProgressStatus.Text = "Connecting hardware & streaming firmware...";

                bool rebootAfter = ChkUatRebootAfterFlash?.IsChecked == true;
                bool checksumVerify = ChkUatChecksumVerify?.IsChecked == true;

                bool ok = false;
                await Task.Run(() =>
                {
                    try
                    {
                        // Clean single-pipeline invocation (loads DA on demand, reads GPT, and writes selected partitions)
                        ok = BSLabBridge.BSLab_MTK_FlashFirmware(port, actualScatterFile, daPath, "", "",
                            rebootAfter,
                            checksumVerify,
                            (step, pct, stage, msg) =>
                            {
                                Dispatcher.Invoke(() =>
                                {
                                    if (ProgressBarUatFlasher != null) ProgressBarUatFlasher.Value = pct;
                                    if (ProgressBarAutoHub != null) ProgressBarAutoHub.Value = pct;
                                    if (TxtUatFlasherProgressPercent != null) TxtUatFlasherProgressPercent.Text = $"{pct}%";
                                    if (TxtUatFlasherProgressStatus != null) TxtUatFlasherProgressStatus.Text = msg;
                                    if (TxtUatFlasherSpeed != null && msg.Contains("MB/s"))
                                    {
                                        var match = System.Text.RegularExpressions.Regex.Match(msg, @"\(([^)]+MB/s)\)");
                                        if (match.Success) TxtUatFlasherSpeed.Text = $"⚡ {match.Groups[1].Value}";
                                    }
                                    AppendAutoHubLog($"[{stage}] {msg}");
                                });
                            });
                    }
                    catch (Exception flashEx)
                    {
                        Dispatcher.Invoke(() => AppendAutoHubLog($"[-] Hardware Flashing Error: {flashEx.Message}"));
                        ok = false;
                    }
                });

                if (ok)
                {
                    if (ProgressBarAutoHub != null) ProgressBarAutoHub.Value = 100;
                    if (ProgressBarUatFlasher != null) ProgressBarUatFlasher.Value = 100;
                    if (TxtUatFlasherProgressPercent != null) TxtUatFlasherProgressPercent.Text = "100%";
                    if (TxtUatFlasherProgressStatus != null) TxtUatFlasherProgressStatus.Text = "✅ Flash Completed Successfully!";
                    if (TxtAutoHubProgressStatus != null) TxtAutoHubProgressStatus.Text = "Firmware Flash Completed Successfully!";
                    if (TxtUatFlasherSpeed != null) TxtUatFlasherSpeed.Text = "⚡ Bus Idle";

                    AppendAutoHubLog("══════════════════════════════════════════════════════════════");
                    AppendAutoHubLog("[+] ✅ FLASH OPERATION COMPLETED 100% SUCCESSFULLY!");
                    AppendAutoHubLog("══════════════════════════════════════════════════════════════");
                }
                else
                {
                    if (ProgressBarAutoHub != null) ProgressBarAutoHub.Value = 0;
                    if (ProgressBarUatFlasher != null) ProgressBarUatFlasher.Value = 0;
                    if (TxtUatFlasherProgressPercent != null) TxtUatFlasherProgressPercent.Text = "0%";
                    if (TxtUatFlasherProgressStatus != null) TxtUatFlasherProgressStatus.Text = "❌ Flashing Failed";
                    AppendAutoHubLog("[-] Hardware Flash Pipeline failed! Ensure device is in BROM mode, battery charged, and correct scatter firmware selected.");
                }
            }
            finally
            {
                _isManualSnifferActive = false;
                if (BtnUatFlashAbort != null) BtnUatFlashAbort.IsEnabled = false;
                if (BtnUatFlashStart != null) BtnUatFlashStart.IsEnabled = true;
            }
        }


        private List<TempRootTargetProfile> _tempRootTargets = new();

        private void InitTempRootDatabase()
        {
            try
            {
                string jsonPath = @"c:\BSLab_Tool\engines\temp_root_targets.json";
                if (File.Exists(jsonPath))
                {
                    string json = File.ReadAllText(jsonPath);
                    var opts = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
                    var targets = JsonSerializer.Deserialize<List<TempRootTargetProfile>>(json, opts);
                    if (targets != null && targets.Count > 0)
                    {
                        _tempRootTargets = targets;
                    }

                }

            }

            catch { }

            if (_tempRootTargets.Count == 0)
            {
                _tempRootTargets = new List<TempRootTargetProfile>
                {
                    new() { Brand = "Samsung Galaxy", Model = "Galaxy S25 / S25+ / S25 Ultra", ModelCode = "SM-S931x / S936x / S938x", Kernel = "6.6.98", Build = "S25 Global/China", Exploit = "GhostLock (CVE-2026-43499)", Loader = "Root My Galaxy", Status = "Tested" },
