        private void OnAiCopyContentClicked(object sender, RoutedEventArgs e)
        {
            try
            {
                if (PanelAiResponseView != null && PanelAiResponseView.Visibility == Visibility.Visible)
                {
                    Clipboard.SetText(TxtAiAssistantResponse?.Text ?? "");
                    AppendAiAnalyseLog("[+] AI Response copied to Windows clipboard.");
                }

                else if (PanelAiTerminalView != null && PanelAiTerminalView.Visibility == Visibility.Visible)
                {
                    Clipboard.SetText(TxtAiAnalyseConsole?.Text ?? "");
                    AppendAiAnalyseLog("[+] Terminal execution log copied to clipboard.");
                }

                else if (PanelAiPropsView != null && PanelAiPropsView.Visibility == Visibility.Visible)
                {
                    Clipboard.SetText(TxtAiRawTelemetry?.Text ?? "");
                    AppendAiAnalyseLog("[+] Raw device telemetry copied to clipboard.");
                }

            }

            catch (Exception ex)
            {
                AppendAiAnalyseLog($"[!] Copy Error: {ex.Message}");
            }

        }


        private void OnAiClearContentClicked(object sender, RoutedEventArgs e)
        {
            if (PanelAiResponseView != null && PanelAiResponseView.Visibility == Visibility.Visible)
            {
                if (TxtAiAssistantResponse != null) TxtAiAssistantResponse.Text = "[*] AI Response cleared by technician. Ready for next prompt.";
            }

            else if (PanelAiTerminalView != null && PanelAiTerminalView.Visibility == Visibility.Visible)
            {
                if (TxtAiAnalyseConsole != null) TxtAiAnalyseConsole.Clear();
            }

        }


        private string GenerateComprehensiveAiResponse(string prompt, AiDiagnosticReport report, AiWorkflowPlan plan)
        {
            string pLower = prompt.ToLowerInvariant();
            var sb = new StringBuilder();
            string timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
            string devInfo = (!string.IsNullOrEmpty(report.Brand) && report.Brand != "Connect Phone via USB") 
                ? $"{report.Brand} {report.Model} (Android {report.AndroidVersion} | {report.CpuAbi})" 
                : "Standalone Bench Mode (No Phone Connected)";

            sb.AppendLine("═══════════════════════════════════════════════════════════════════════════════");
            sb.AppendLine("🤖 BS LAB AI EXPERT ASSISTANT — HARDWARE & GSM REPAIR INTELLIGENCE");
            sb.AppendLine($"[+] Analysis Timestamp : {timestamp}");
            sb.AppendLine($"[+] Target Device      : {devInfo}");
            sb.AppendLine($"[+] Classified Action  : {plan.Title}");
            sb.AppendLine($"[+] Hardware Safety    : {plan.RiskLevel}");
            sb.AppendLine("═══════════════════════════════════════════════════════════════════════════════");
            sb.AppendLine();

            if (plan.ActionType == "AdbFastbootMaster" || pLower.Contains("adb") || pLower.Contains("fastboot"))
            {
                sb.AppendLine("Shah Ji, aapke prompt ke mutabiq COMPLETE ADB & FASTBOOT CLI MASTER MATRIX yeh hai:");
                sb.AppendLine();
                sb.AppendLine("📌 1. CORE ADB COMMANDS (DEVICE ENUMERATION & SYSTEM INSPECTION):");
                sb.AppendLine("   ----------------------------------------------------------------------------");
                sb.AppendLine("   • adb devices -l                        -> Connect hui devices ko unke model aur USB bus ke sath list karein.");
                sb.AppendLine("   • adb start-server / kill-server        -> ADB server background daemon ko restart karein.");
                sb.AppendLine("   • adb get-serialno                      -> Connected phone ka unique serial number extract karein.");
                sb.AppendLine("   • adb shell getprop                     -> Device ki tamam OS system properties aur fingerprints harvest karein.");
                sb.AppendLine("   • adb install -r -d target.apk          -> Existing data rakhte huwe app ko force-reinstall / downgrade karein.");
                sb.AppendLine("   • adb push <local_path> <remote_path>   -> PC se file phone mein bhejein (e.g. /data/local/tmp/).");
                sb.AppendLine("   • adb pull <remote_path> <local_path>   -> Phone se partition ya file PC par extract karein.");
                sb.AppendLine();
                sb.AppendLine("📌 2. ROOT SHELL & SELINUX PERMISSION CONTROL:");
                sb.AppendLine("   ----------------------------------------------------------------------------");
                sb.AppendLine("   • adb shell su                          -> Root superuser privileges (UID 0) access karein.");
                sb.AppendLine("   • adb shell getenforce                  -> SELinux state check karein (Enforcing ya Permissive).");
                sb.AppendLine("   • adb shell setenforce 0                -> SELinux ko Permissive karein (Direct block I/O unblock karne ke liye).");
                sb.AppendLine("   • adb shell pm disable-user --user 0 <pkg> -> Google SetupWizard ya Demo lock service ko bypass karein.");
                sb.AppendLine("   • adb logcat -b radio -d                -> Modem RIL, baseband power aur SIM registration logs inspect karein.");
                sb.AppendLine("   • adb shell dumpsys telephony.registry  -> Live radio power state (mRadioPowerState) aur network check karein.");
                sb.AppendLine();
                sb.AppendLine("📌 3. FASTBOOT BOOTLOADER & PARTITION FLASHING:");
                sb.AppendLine("   ----------------------------------------------------------------------------");
                sb.AppendLine("   • fastboot devices                      -> Bootloader mode mein connect devices detect karein.");
                sb.AppendLine("   • fastboot getvar all                   -> Bootloader lock status, secure boot, aur product specs read karein.");
                sb.AppendLine("   • fastboot oem unlock                   -> Legacy devices par bootloader unlock karein.");
                sb.AppendLine("   • fastboot flashing unlock              -> Modern Android devices par bootloader unlock karein.");
                sb.AppendLine("   • fastboot flash boot boot.img          -> Kernel boot image direct flash karein.");
                sb.AppendLine("   • fastboot flash recovery recovery.img  -> Custom recovery (TWRP/OrangeFox) flash karein.");
                sb.AppendLine("   • fastboot flash vbmeta --disable-verity --disable-verification vbmeta.img -> AVB 2.0 unbrick ke liye.");
                sb.AppendLine("   • fastboot reboot fastboot              -> Android 10+ dynamic Super partition flasher (Fastbootd) mein jayein.");
                sb.AppendLine("   • fastboot flash super super.img        -> Full multi-system dynamic super partition update karein.");
            }

            else if (plan.ActionType == "RebootModeSwitcher" || pLower.Contains("reboot") || pLower.Contains("mode"))
            {
                sb.AppendLine("Shah Ji, phone ko SABHI MODES MEIN SWITCH KARNE KE CLI COMMANDS AUR HARDWARE VECTORS yeh hain:");
                sb.AppendLine();
                sb.AppendLine("📌 1. ADB SE MODES SWITCH KARNA (PHONE NORMAL OS MEIN HO):");
                sb.AppendLine("   ----------------------------------------------------------------------------");
                sb.AppendLine("   • adb reboot                            -> Phone ko normal restart karein.");
                sb.AppendLine("   • adb reboot bootloader                 -> Phone ko Fastboot / Bootloader mode mein switch karein.");
                sb.AppendLine("   • adb reboot recovery                   -> Phone ko Recovery Mode (Stock / TWRP) mein bhejein.");
                sb.AppendLine("   • adb reboot edl                        -> Qualcomm Snapdragon ko Emergency Download (EDL 9008) mein switch karein.");
                sb.AppendLine("   • adb reboot fastboot                   -> Android 10+ userspace Fastbootd mode mein bhejein.");
                sb.AppendLine("   • adb reboot download                   -> Samsung device ko direct Odin Download mode mein bhejein.");
                sb.AppendLine("   • adb reboot sideload                   -> Recovery ADB Sideload OTA update mode mein switch karein.");
                sb.AppendLine();
                sb.AppendLine("📌 2. FASTBOOT SE MODES SWITCH KARNA (PHONE FASTBOOT MEIN HO):");
                sb.AppendLine("   ----------------------------------------------------------------------------");
                sb.AppendLine("   • fastboot reboot                       -> Phone ko wapas Normal Android mein boot karein.");
                sb.AppendLine("   • fastboot reboot-bootloader            -> Bootloader interface ko re-initialize karein.");
                sb.AppendLine("   • fastboot reboot recovery              -> Fastboot se seedha Recovery partition par boot karein.");
                sb.AppendLine("   • fastboot reboot fastboot              -> Bootloader se Fastbootd (Dynamic Super) mein jump karein.");
                sb.AppendLine("   • fastboot oem edl / fastboot reboot-edl -> Fastboot se Qualcomm 9008 mode force karein.");
                sb.AppendLine();
                sb.AppendLine("📌 3. HARDWARE KEY COMBINATIONS (PHONE POWER OFF HO):");
                sb.AppendLine("   ----------------------------------------------------------------------------");
                sb.AppendLine("   • MediaTek (BROM Mode)                  -> Phone Off karein -> [Vol-] aur [Vol+] daba kar USB lagayein.");
                sb.AppendLine("   • Unisoc / SPD (FDL Mode)               -> Phone Off karein -> [Vol-] daba kar USB lagayein.");
                sb.AppendLine("   • Samsung (Odin Download Mode)          -> Phone Off karein -> [Vol-] aur [Vol+] daba kar USB lagayein -> [Vol+] dabayein.");
                sb.AppendLine("   • Qualcomm (EDL 9008 Testpoint)         -> Motherboard par EDL Testpoint (TP) ko GND (1.8V) se short karke USB lagayein.");
                sb.AppendLine("   • Apple iOS (DFU Mode)                  -> Power (3s) -> Vol- + Power (10s) -> Power release karein.");
            }

            else if (plan.ActionType == "SocArchitecture" || pLower.Contains("soc") || pLower.Contains("qualcomm") || pLower.Contains("mediatek"))
            {
                sb.AppendLine("Shah Ji, TAMAM MOBILE SOCS KI BOOT ARCHITECTURE AUR FLASHER PROTOCOLS yeh hain:");
                sb.AppendLine();
                sb.AppendLine("📌 1. QUALCOMM SNAPDRAGON (MSM / SDM / SM):");
                sb.AppendLine("   • Boot Chain: PBL (ROM) -> XBL -> TrustZone (QSEE) -> ABOOT -> Kernel.");
                sb.AppendLine("   • Emergency Flasher: Sahara Protocol (Hello, Command, MemDump) -> Firehose XML (rawprogram0.xml).");
                sb.AppendLine("   • Diagnostic: DIAG 9008 / 900E / 903A (HDLC packet framing, SPC 000000, NV Item 550, QCN RF sync).");
                sb.AppendLine();
                sb.AppendLine("📌 2. MEDIATEK (MTK HELIO / DIMENSITY):");
                sb.AppendLine("   • Boot Chain: BootROM (BROM) -> Preloader -> LK (Little Kernel) -> TEE -> Kernel.");
                sb.AppendLine("   • BROM Handshake: 0xA0 0x0A 0x50 0x05 sync sequence.");
                sb.AppendLine("   • Auth Bypass: Hardware Watchdog (Register 0x10007000) disable karke USBDL payload inject karna.");
                sb.AppendLine("   • Flasher & Meta: DA1 (Internal SRAM) -> DA2 (External DRAM) -> Meta Mode (Port 0x1634).");
                sb.AppendLine();
                sb.AppendLine("📌 3. UNISOC / SPREADTRUM (SC / TIGER T-SERIES):");
                sb.AppendLine("   • Boot Chain: BootROM -> FDL1 (SRAM) -> FDL2 (DDR RAM) -> U-Boot -> Kernel.");
                sb.AppendLine("   • Baudrate: 921600 bps high-speed B-Channel flasher protocol; PAC file architecture.");
                sb.AppendLine();
                sb.AppendLine("📌 4. SAMSUNG EXYNOS & SHANNON BASEBAND:");
                sb.AppendLine("   • Boot Chain: iROM (BL1) -> BL2 -> S-Boot -> Kernel.");
                sb.AppendLine("   • Flasher: Samsung Loke / Odin protocol via USB bulk endpoints; PIT table memory mapping.");
                sb.AppendLine("   • Security: Knox hardware eFuse (0x0 vs 0x1) aur KG / RMM state management.");
            }

            else if (plan.ActionType == "PartitionDoctor" || pLower.Contains("partition") || pLower.Contains("dump") || pLower.Contains("erase"))
            {
                sb.AppendLine("Shah Ji, PHYSICAL PARTITIONS READING, DUMPING, ERASING AUR WRITING KA COMPLETE GUIDE:");
                sb.AppendLine();
                sb.AppendLine("📌 1. SECTOR MATHEMATICS & LBA ADDRESSING:");
                sb.AppendLine("   • Sector Size: 512 Bytes (eMMC) / 4096 Bytes (Modern UFS 2.x - 4.x).");
                sb.AppendLine("   • Formula: Byte Offset = LBA (Start Sector) * Sector Size.");
                sb.AppendLine("   • Example: LBA 0x00008000 (32768) * 512 = 16,777,216 Bytes (16 MB Offset).");
                sb.AppendLine("   • GPT Layout: LBA 0 (Protective MBR) -> LBA 1 (Primary GPT) -> LBA 2-33 (Partition Entries 1-128).");
                sb.AppendLine();
                sb.AppendLine("📌 2. READING & DUMPING PARTITIONS:");
                sb.AppendLine("   • Qualcomm Firehose: <read SECTOR_SIZE_IN_BYTES=\"512\" num_partition_sectors=\"...\" start_sector=\"...\" filename=\"boot.bin\"/>");
                sb.AppendLine("   • MediaTek DA: DA_READ_RANGE memory range dump to local storage.");
                sb.AppendLine("   • Live Root Android: dd if=/dev/block/by-name/<part> of=/sdcard/<part>.bin bs=4096 status=progress");
                sb.AppendLine();
                sb.AppendLine("📌 3. ZERO-BRICK ERASING RULES:");
                sb.AppendLine("   • Safe to Erase/Wipe: Cache, Userdata, Dalvik, Metadata, temporary scratch buffers.");
                sb.AppendLine("   • ⚠️ NEVER ERASE: Signed bootloader anchors (xbl, abl, bootloader, rpm, tz) on secured devices!");
                sb.AppendLine("   • Fastboot Erase: fastboot erase <part> ya fastboot format:ext4 <part>.");
                sb.AppendLine();
                sb.AppendLine("📌 4. WRITING & FLASHING SAFELY:");
                sb.AppendLine("   • Sparse Unpacking: Android system/super partitions ko unsparse (simg2img) ya sparse engine se likhein.");
                sb.AppendLine("   • Checksum Verification: Post-flash SHA-256 hash verify karein before rebooting.");
                sb.AppendLine("   • Security Partitions Matrix: Qualcomm (modemst1/2, fsg) | MTK (nvram, nvdata) | SPD (prodnv) | Samsung (efs).");
            }

            else if (plan.ActionType == "BasebandRepair" || pLower.Contains("baseband") || pLower.Contains("imei") || pLower.Contains("null") || pLower.Contains("sim") || pLower.Contains("radio"))
            {
                sb.AppendLine("Shah Ji, NULL BASEBAND / MODEM CORRUPTION REPAIR KA PROFESSIONAL ZERO-DATA PROTOCOL:");
                sb.AppendLine();
                sb.AppendLine("📌 1. HARDWARE MODEM & CALIBRATION ARCHITECTURE:");
                sb.AppendLine("   • Qualcomm: Baseband radio partition tree: modemst1 (EFS Primary), modemst2 (EFS Secondary), fsg (Golden Copy), fsc, persist.");
                sb.AppendLine("   • MediaTek: NVRAM (Persistent Raw Partition) + NVDATA (/data/nvram Runtime Cached Calibrations).");
                sb.AppendLine("   • Samsung: EFS block + sec_efs (Cryptographically signed radio calibration data).");
                sb.AppendLine("   • Unisoc / SPD: prodnv + miscdata (Factory RF calibration sector).");
                sb.AppendLine();
                sb.AppendLine("📌 2. AUTOMATIC PRE-FLIGHT SNAPSHOT & SECURITY GUARD:");
                sb.AppendLine("   • BSLab Tool sab se pehle connected device ke active EFS / NVRAM partitions ka bit-by-bit backup disk par create karta hai.");
                sb.AppendLine("   • Customer ki photos, messages, apps 100% untouched rehti hain.");
                sb.AppendLine();
                sb.AppendLine("📌 3. SURGICAL BASEBAND RECOVERY SEQUENCE:");
                sb.AppendLine("   • Step 1: Flushing corrupted radio cache (adb shell rm -rf /data/vendor/radio/*).");
                sb.AppendLine("   • Step 2: Modem firmware reflash (fastboot flash modem NON-HLOS.bin ya MTK DA flash md1img).");
                sb.AppendLine("   • Step 3: Diagnostic Port Open (setprop sys.usb.config diag,serial_cdev,rmnet,adb) & QCN RF sync.");
                sb.AppendLine("   • Step 4: Radio interface reboot (kill -9 rild daemon & watchdog radio handshake).");
            }

            else if (plan.ActionType == "FrpBypass" || pLower.Contains("frp") || pLower.Contains("google") || pLower.Contains("account"))
            {
                sb.AppendLine("Shah Ji, GOOGLE ACCOUNT / FRP LOCK REMOVAL KA PROFESSIONAL ZERO-BRICK GUIDE:");
                sb.AppendLine();
                sb.AppendLine("📌 1. FACTORY RESET PROTECTION (FRP) MECHANISM:");
                sb.AppendLine("   • FRP partition block mein OEM lock state aur Google Account Auth Token store hota hai.");
                sb.AppendLine("   • Partition locations: /dev/block/by-name/frp (Qualcomm/MTK) ya /dev/block/by-name/config.");
                sb.AppendLine();
                sb.AppendLine("📌 2. MULTI-CHIPSET BYPASS METHODS:");
                sb.AppendLine("   • MediaTek: MTK BROM Mode mein Watchdog disable karke FRP partition ko zero-fill erase karna.");
                sb.AppendLine("   • Qualcomm: EDL 9008 Sahara/Firehose se rawprogram0.xml mein frp sector par <erase/> command bhejna.");
                sb.AppendLine("   • Fastboot Mode: fastboot erase frp ya fastboot erase config.");
                sb.AppendLine("   • Samsung MTP: Emergency Dialer (*#0*#) se Test Mode open karke Enable ADB command send karna.");
                sb.AppendLine();
                sb.AppendLine("📌 3. POST-BYPASS SETUP INTENT:");
                sb.AppendLine("   • adb shell am start -n com.google.android.setupwizard/.SetupWizardTestActivity");
                sb.AppendLine("   • adb shell content insert --uri content://settings/secure --bind name:s:user_setup_complete --bind value:s:1");
            }

            else if (plan.ActionType == "BootloopFix" || pLower.Contains("bootloop") || pLower.Contains("restart") || pLower.Contains("logo") || pLower.Contains("verity") || pLower.Contains("stuck"))
            {
                sb.AppendLine("Shah Ji, PHONE BOOTLOOP & DM-VERITY SYSTEM REPAIR KA PROFESSIONAL PROTOCOL:");
                sb.AppendLine();
                sb.AppendLine("📌 1. BOOTLOOP DIAGNOSTIC CLASSIFICATION:");
                sb.AppendLine("   • Stage 1 (Hard Bootloop): 1st Vendor Logo par restart -> Kernel panic ya boot/dtbo signature failure.");
                sb.AppendLine("   • Stage 2 (Soft Bootloop): Android Boot Animation par stuck -> System/Super partition mismatch ya corrupt Dalvik cache.");
                sb.AppendLine("   • Stage 3 (AVB/DM-Verity Fail): 'Your device is corrupt and cannot be trusted' -> vbmeta verification hash mismatch.");
                sb.AppendLine();
                sb.AppendLine("📌 2. REPAIR STRATEGY (100% DATA SAFE):");
                sb.AppendLine("   • AVB 2.0 Patch: fastboot flash vbmeta --disable-verity --disable-verification vbmeta.img.");
                sb.AppendLine("   • Stock Kernel Flash: fastboot flash boot boot.img.");
                sb.AppendLine("   • Cache Flush: fastboot erase cache && fastboot erase metadata (Userdata untouched!).");
            }

            else if (plan.ActionType == "ScreenLockRemove" || pLower.Contains("lock") || pLower.Contains("screen") || pLower.Contains("pattern") || pLower.Contains("pin") || pLower.Contains("password"))
            {
                sb.AppendLine("Shah Ji, SCREEN LOCK / PATTERN REMOVAL (KEEP USER DATA 100% INTACT):");
                sb.AppendLine();
                sb.AppendLine("📌 1. ANDROID LOCK CREDENTIAL ARCHITECTURE:");
                sb.AppendLine("   • Security Container: /data/system/ directory.");
                sb.AppendLine("   • Files: locksettings.db, gatekeeper.password.key, gatekeeper.pattern.key, biometric.db.");
                sb.AppendLine();
                sb.AppendLine("📌 2. SURGICAL REMOVAL WITHOUT FACTORY RESET:");
                sb.AppendLine("   • Root / Recovery Mode: adb shell rm -f /data/system/locksettings.db*");
                sb.AppendLine("   • adb shell rm -f /data/system/gatekeeper.*");
                sb.AppendLine("   • Soft reboot device -> Phone seedha Swipe to Unlock mode mein boot hoga, tamam photos, videos aur WhatsApp data safe rahega!");
            }

            else if (plan.ActionType == "MiAccountBypass" || pLower.Contains("mi account") || pLower.Contains("mi cloud") || pLower.Contains("xiaomi"))
            {
                sb.AppendLine("Shah Ji, XIAOMI MI ACCOUNT & FIND DEVICE BYPASS PROTOCOL:");
                sb.AppendLine();
                sb.AppendLine("📌 1. MI ACCOUNT AUTHENTICATION MECHANISM:");
                sb.AppendLine("   • Security token persist partition (persist/data/cloud/) aur MiuiAccount.apk daemon mein lock rehta hai.");
                sb.AppendLine("   • Wi-Fi connect hote hi device dubara relock ho jati hai agar daemon ko disable na kiya jaye.");
                sb.AppendLine();
                sb.AppendLine("📌 2. SURGICAL BYPASS & ANTI-RELOCK GUARD:");
                sb.AppendLine("   • Step 1: Persist partition format / patch via Fastboot ya Qualcomm EDL 9008.");
                sb.AppendLine("   • Step 2: adb shell pm disable-user --user 0 com.xiaomi.finddevice.");
                sb.AppendLine("   • Step 3: adb shell pm disable-user --user 0 com.miui.cloudservice.");
                sb.AppendLine("   • Step 4: Wi-Fi reconnect karein -> No Relock, completely permanent bypass!");
            }

            else if (plan.ActionType == "HuaweiManufactureExit" || pLower.Contains("manufacture") || pLower.Contains("pcui") || pLower.Contains("hdb"))
            {
                sb.AppendLine("Shah Ji, HUAWEI MANUFACTURE MODE EXIT & RESET PROTOCOL:");
                sb.AppendLine();
                sb.AppendLine("📌 1. MANUFACTURE MODE (PCUI / DBADAPTER):");
                sb.AppendLine("   • Mode code: *#*#2846579#*#* -> Background Settings -> USB Port Settings -> Manufacture Mode.");
                sb.AppendLine("   • Serial Port: HUAWEI Mobile Connect - PCUI / DBAdapter COM Port.");
                sb.AppendLine();
                sb.AppendLine("📌 2. EXIT PROTOCOL VIA AT MODEM COMMAND:");
                sb.AppendLine("   • Open PCUI COM Port @ 115200 Baud.");
                sb.AppendLine("   • Send Command: AT^DATAMODE=0\\r\\n (Standard User Data Mode).");
                sb.AppendLine("   • Send Command: AT^RESET\\r\\n (Watchdog hardware reset).");
                sb.AppendLine("   • USB subsystem automatically switches to MTP + ADB standard mode.");
            }

            else
            {
                sb.AppendLine($"Shah Ji, aapke sawaal: \"{prompt}\" ka diagnostic tajziya yeh hai:");
                sb.AppendLine();
                sb.AppendLine($"📌 1. DETECTED ISSUE & CLASSIFICATION:");
                sb.AppendLine($"   • Problem Category : {plan.Title}");
                sb.AppendLine($"   • Risk Assessment  : {plan.RiskLevel}");
                sb.AppendLine($"   • Diagnosis Details: {plan.IssueDetected}");
                sb.AppendLine();
                sb.AppendLine("📌 2. RECOMMENDED STEP-BY-STEP REPAIR PROTOCOL:");
                for (int i = 0; i < plan.Steps.Count; i++)
                {
                    sb.AppendLine($"   {plan.Steps[i]}");
                }

                sb.AppendLine();
                sb.AppendLine("📌 3. TECHNICIAN VERIFICATION & EXECUTION:");
                sb.AppendLine("   Neeche 'AUTHORIZE & EXECUTE WORKFLOW' button dabayein taake tool is workflow ko live execute kare.");
            }


            sb.AppendLine();
            sb.AppendLine("═══════════════════════════════════════════════════════════════════════════════");
            sb.AppendLine("💡 TIP: Kisi bhi button ya command par click karne se pehle Zero-Brick checkpoint active hota hai.");
            sb.AppendLine("═══════════════════════════════════════════════════════════════════════════════");

            return sb.ToString();
        }


        private void OnAiAskAndPlanClicked(object sender, RoutedEventArgs e)

        {

            string prompt = TxtAiTechnicianPrompt.Text.Trim();

            if (string.IsNullOrEmpty(prompt))

            {

                prompt = "Analyze device state and recommend optimal repair workflow.";

            }




            AppendAutoHubLog($"[*] AI Prompt Ingested: \"{prompt}\"");

            AppendAiAnalyseLog($"[*] AI Prompt Ingested: \"{prompt}\"");

            var plan = GenerateAiWorkflowPlan(prompt, _currentAiReport);

            _currentAiWorkflow = plan;



            TxtAiWorkflowTitle.Text = plan.Title;

            TxtAiWorkflowRisk.Text = $"🛡️ RISK: {plan.RiskLevel}";

            TxtAiWorkflowSteps.Text = string.Join("\n", plan.Steps);



            BorderAiWorkflowCard.Visibility = Visibility.Visible;

            PanelAiWorkflowProgress.Visibility = Visibility.Collapsed;



            AppendAutoHubLog($"[+] AI Reasoning Complete: {plan.Title} formulated. Awaiting technician authorization.");
            AppendAiAnalyseLog($"[+] AI Reasoning Complete: {plan.Title} formulated. Awaiting technician authorization.");
            PrintProfessionalKnowledgeDossier(plan.ActionType, prompt);

            // Generate and display the rich AI Expert Response directly on screen
            string aiResponse = GenerateComprehensiveAiResponse(prompt, _currentAiReport, plan);
            if (TxtAiAssistantResponse != null)
            {
                TxtAiAssistantResponse.Text = aiResponse;
                TxtAiAssistantResponse.Background = new SolidColorBrush(Color.FromRgb(0x0A, 0x0E, 0x1A));
                TxtAiAssistantResponse.Foreground = new SolidColorBrush(Color.FromRgb(0x38, 0xBD, 0xF8));
            }

            if (PanelAiResponseView != null)
            {
                PanelAiResponseView.Background = new SolidColorBrush(Color.FromRgb(0x0A, 0x0E, 0x1A));
            }

            if (TxtAiResponseHeader != null)
            {
                TxtAiResponseHeader.Text = $"🤖 AI RESPONSE: {plan.Title}";
                TxtAiResponseHeader.Foreground = new SolidColorBrush(Color.FromRgb(0x38, 0xBD, 0xF8));
            }

            OnAiSubTabResponseClicked(null, null);
        }




        private AiWorkflowPlan GenerateAiWorkflowPlan(string prompt, AiDiagnosticReport report)
        {
            string pLower = prompt.ToLowerInvariant();
            var plan = new AiWorkflowPlan();

            // Priority 1: Check user prompt explicitly FIRST before falling back to report flags
            if (pLower.Contains("adb") || pLower.Contains("fastboot") || pLower.Contains("terminal") || pLower.Contains("cli") || pLower.Contains("command"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: ADVANCED ADB & FASTBOOT CLI MASTER MATRIX";
                plan.IssueDetected = "Technician requested comprehensive ADB & Fastboot terminal command protocols, live device queries, and flashing syntax.";
                plan.RiskLevel = "UNIVERSAL CLI PROTOCOL (ZERO BRICK)";
                plan.ActionType = "AdbFastbootMaster";
                plan.Steps = new List<string>
                {
                    "1. [ADB Core]: adb devices -l (Link check) | adb shell getprop (OS properties) | adb install -r -d app.apk | adb push/pull",
                    "2. [ADB Shell & RIL]: adb shell su (Root Terminal) | getenforce | setenforce 0 | pm disable-user --user 0 <pkg> | logcat -b radio",
                    "3. [Fastboot Core]: fastboot devices | fastboot getvar all (product, unlocked, secure) | fastboot oem get_unlock_data",
                    "4. [Fastboot Flash]: fastboot flash boot boot.img | fastboot flash recovery recovery.img | fastboot flash vbmeta --disable-verity --disable-verification vbmeta.img",
                    "5. [Fastbootd Userspace]: fastboot reboot fastboot (Dynamic Super Partitions Android 10+) | fastboot flash super super.img | fastboot delete-logical-partition",
                    "6. [Authorization]: Click 'AUTHORIZE & EXECUTE' to trigger live hardware enumeration sweep & generate offline CLI script."
                }
;
            }

            else if (pLower.Contains("reboot") || pLower.Contains("mode") || pLower.Contains("edl") || pLower.Contains("brom") || pLower.Contains("recovery") || pLower.Contains("download") || pLower.Contains("fastbootd") || pLower.Contains("purple") || pLower.Contains("meta"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: HARDWARE BOOT VECTORS & MODE SWITCHER";
                plan.IssueDetected = "Technician requested multi-mode switching vectors across ADB, Fastboot, and Silicon Hardware BootROMs.";
                plan.RiskLevel = "SAFE (SYSTEM REBOOT CONTROL)";
                plan.ActionType = "RebootModeSwitcher";
                plan.Steps = new List<string>
                {
                    "1. [ADB Vectors]: adb reboot (Normal) | adb reboot bootloader (Fastboot) | adb reboot recovery (Stock/TWRP)",
                    "2. [Deep Qualcomm Vectors]: adb reboot edl (EDL 9008) | fastboot oem edl | fastboot reboot-edl | Hardware TP to GND (1.8V)",
                    "3. [Modern Fastbootd]: adb reboot fastboot | fastboot reboot fastboot (Android 10+ Dynamic Super Partitions)",
                    "4. [Samsung & Sideload]: adb reboot download (Odin Mode) | adb reboot sideload (OTA Update Mode)",
                    "5. [Hardware Key Vectors]: MTK BROM (Vol- & Vol+ with USB) | SPD/Unisoc (Vol-) | Samsung (Vol- & Vol+ with USB) | iOS DFU (Vol- + Power)",
                    "6. [Authorization]: Click 'AUTHORIZE & EXECUTE' to dispatch active reboot vector to connected device."
                }
;
            }

            else if (pLower.Contains("soc") || pLower.Contains("qualcomm") || pLower.Contains("snapdragon") || pLower.Contains("mediatek") || pLower.Contains("mtk") || pLower.Contains("unisoc") || pLower.Contains("spreadtrum") || pLower.Contains("spd") || pLower.Contains("exynos") || pLower.Contains("kirin") || pLower.Contains("apple") || pLower.Contains("chip"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: MULTI-SOC SILICON ARCHITECTURE & PROTOCOLS";
                plan.IssueDetected = "Technician requested deep hardware boot and flasher protocol specifications across all mobile chipsets.";
                plan.RiskLevel = "HARDWARE ARCHITECTURE SPECIFICATION";
                plan.ActionType = "SocArchitecture";
                plan.Steps = new List<string>
                {
                    "1. [Qualcomm Snapdragon]: PBL -> Sahara Protocol (Hello, Cmd, MemDump) -> Firehose XML (rawprogram0.xml, patch0.xml) -> Diag 9008/900E",
                    "2. [MediaTek Helio/Dimensity]: BootROM Handshake (0xA0 0x0A 0x50 0x05) -> Disable Watchdog (0x10007000) -> SLA/DAA Bypass -> DA1/DA2 -> Meta Mode (0x1634)",
                    "3. [Unisoc / Spreadtrum]: FDL1 Bootloader Handshake -> Baudrate Switch (up to 921600 bps) -> FDL2 DRAM Injection -> B-Channel Flasher -> PAC Extraction",
                    "4. [Samsung Exynos]: Shannon Modem Architecture -> PIT (Partition Information Table) Mapping -> Odin TAR v1/v2 Packaging -> Knox Trip Check (0x0/0x1)",
                    "5. [HiSilicon Kirin & Apple]: Kirin USB COM 1.0 (xloader) / Manufacture Mode (*#*#2846579#*#*) | Apple Checkm8 DFU & Purple SysCfg Editor",
                    "6. [Authorization]: Click 'AUTHORIZE & EXECUTE' to generate comprehensive Silicon Specification Dossier."
                }
;
            }

            else if (pLower.Contains("partition") || pLower.Contains("dump") || pLower.Contains("erase") || pLower.Contains("wipe") || pLower.Contains("writing") || pLower.Contains("write") || pLower.Contains("efs") || pLower.Contains("nvram") || pLower.Contains("gpt") || pLower.Contains("super"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: PARTITIONS DOCTOR (READ / DUMP / ERASE / WRITE)";
                plan.IssueDetected = "Technician requested low-level block sector engineering, partition dumping, and safe flashing guidelines.";
                plan.RiskLevel = "SURGICAL SECTOR ENGINEERING (ANTI-BRICK ACTIVE)";
                plan.ActionType = "PartitionDoctor";
                plan.Steps = new List<string>
                {
                    "1. [Sector Math & LBA]: LBA * SectorSize (512B / 4096B UFS) = Byte Offset | Primary GPT (LBA 1), Partition Entries (LBA 2-33)",
                    "2. [Reading / Dumping]: Direct Block Read via Firehose XML (<read .../>), MTK DA_READ_RANGE, or adb dd if=/dev/block/by-name/<part>",
                    "3. [Erasing & Zero-Filling]: Clean volatile cache zero-filling (<erase .../> or fastboot erase <part>) | NEVER erase signed boot anchors",
                    "4. [Writing & Flashing]: Pre-flash boundary check, sparse simg2img decompression, <program .../>, fastboot flash, CRC32/SHA256 verification",
                    "5. [Security Partitions Matrix]: QC: modemst1, modemst2, fsg, persist | MTK: nvram, nvdata, protect_f/s | SPD: prodnv | Samsung: efs",
                    "6. [Super Dynamic Partitions]: Android 10+ super partition houses logical blocks (system, vendor, product, odm, system_ext)",
                    "7. [Safety Guard]: Automatic zero-brick pre-flight snapshot committed to backups/partitions before any sector wipe or flash."
                }
;
            }

            else if (pLower.Contains("read info") || pLower.Contains("readinfo") || pLower.Contains("info lo") || pLower.Contains("device info") || pLower.Contains("getprop") || pLower.Contains("check info") || pLower.Contains("check device"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: DEEP ADB DEVICE IDENTIFICATION & TELEMETRY";
                plan.IssueDetected = "Technician requested live ADB hardware inspection & OS properties sweep.";
                plan.RiskLevel = "ZERO RISK (READ-ONLY SWEEP)";
                plan.ActionType = "AdbReadInfo";
