                    "4. Synthesize diagnostic data into AI Inspector and copy summary to clipboard"
                }
;
            }

            else if (pLower.Contains("menufecture") || pLower.Contains("manufacture") || pLower.Contains("pcui") || pLower.Contains("hdb"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: HUAWEI MANUFACTURE MODE EXIT / TOGGLE";
                plan.IssueDetected = "Device currently active in Huawei Manufacture Mode (PCUI / DBAdapter active).";
                plan.RiskLevel = "SAFE (ZERO DATA LOSS)";
                plan.ActionType = "HuaweiManufactureExit";
                plan.Steps = new List<string>
                {
                    "1. Connect to Android Adapter PCUI diagnostic serial channel (COM111)",
                    "2. Transmit AT modem exit command (AT^DATAMODE=0 / AT^RESET)",
                    "3. Reset Android composite USB subsystem configuration (setprop sys.usb.config mtp,adb)",
                    "4. Watchdog soft-reboot device into Standard User Mode"
                }
;
            }

            else if (pLower.Contains("frp") || pLower.Contains("google") || pLower.Contains("account"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: UNIVERSAL FRP & ACCOUNT BYPASS";
                plan.IssueDetected = "Persistent factory reset protection active on device storage.";
                plan.RiskLevel = "SAFE (ZERO BRICK)";
                plan.ActionType = "FrpBypass";
                plan.Steps = new List<string>
                {
                    "1. Locate persistent lock block (frp / config) partition offset",
