                }
;
            }

            else if (pLower.Contains("bootloop") || pLower.Contains("restart") || pLower.Contains("logo") || pLower.Contains("verity") || pLower.Contains("stuck"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: BOOTLOOP & DM-VERITY UNBRICK";
                plan.IssueDetected = "Bootloader verification failure or boot partition corruption detected.";
                plan.RiskLevel = "SAFE (DATA PRESERVED)";
                plan.ActionType = "BootloopFix";
                plan.Steps = new List<string>
                {
                    "1. Dump pre-flight backup of boot, dtbo & vbmeta partitions",
                    "2. Patch vbmeta with --disable-verity and --disable-verification flags",
                    "3. Wipe corrupt Dalvik cache & temporary ART runtime buffers",
                    "4. Hardware soft-reboot into normal system mode"
                }
;
            }

            else if (pLower.Contains("lock") || pLower.Contains("screen") || pLower.Contains("pattern") || pLower.Contains("pin") || pLower.Contains("password"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: SCREEN LOCK REMOVAL (KEEP DATA)";
