;
            }

            else if (pLower.Contains("backup") || pLower.Contains("whatsapp") || pLower.Contains("clone") || pLower.Contains("session"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: 1-CLICK DISASTER BACKUP & WHATSAPP VAULT";
                plan.IssueDetected = "Technician requested emergency cryptographic data extraction.";
                plan.RiskLevel = "ZERO RISK (100% READ ONLY)";
