                }
;
            }

            else if (pLower.Contains("baseband") || pLower.Contains("imei") || pLower.Contains("null") || pLower.Contains("sim") || pLower.Contains("network"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: NVRAM & BASEBAND RESTORATION";
