            }

            else if (pLower.Contains("mi cloud") || pLower.Contains("mi account") || pLower.Contains("xiaomi"))
            {
                plan.Title = "⚡ SURGICAL WORKFLOW: XIAOMI MI ACCOUNT & FIND DEVICE BYPASS";
