        // --- Flasher Handlers ---
        private void UpdateUatFlasherCount()
        {
            if (TxtUatFlasherCount == null) return;
            int total = _autoHubPartitions.Count;
            int sel = _autoHubPartitions.Count(p => p.IsChecked);
            TxtUatFlasherCount.Text = $" ({total} Partitions | {sel} Selected)";
        }

        private void OnUatFlasherSelectAllClicked(object sender, RoutedEventArgs e)
        {
            foreach (var p in _autoHubPartitions) p.IsChecked = true;
            if (GridUatFlasherPartitions != null)
            {
                GridUatFlasherPartitions.ItemsSource = null;
                GridUatFlasherPartitions.ItemsSource = _autoHubPartitions;
            }
            UpdateUatFlasherCount();
            AppendAutoHubLog("[+] Flasher: Selected all partitions.");
        }

        private void OnUatFlasherDeselectAllClicked(object sender, RoutedEventArgs e)
        {
            foreach (var p in _autoHubPartitions) p.IsChecked = false;
            if (GridUatFlasherPartitions != null)
            {
                GridUatFlasherPartitions.ItemsSource = null;
                GridUatFlasherPartitions.ItemsSource = _autoHubPartitions;
            }
            UpdateUatFlasherCount();
            AppendAutoHubLog("[*] Flasher: Deselected all partitions.");
        }

        private void OnUatFlasherSearchTextChanged(object sender, TextChangedEventArgs e)
        {
            if (GridUatFlasherPartitions == null) return;
            string query = TxtUatFlasherSearch?.Text?.Trim() ?? "";
            if (string.IsNullOrEmpty(query))
            {
                GridUatFlasherPartitions.ItemsSource = null;
                GridUatFlasherPartitions.ItemsSource = _autoHubPartitions;
            }
            else
            {
                var filtered = _autoHubPartitions.Where(p => (p.Name != null && p.Name.Contains(query, StringComparison.OrdinalIgnoreCase))).ToList();
                GridUatFlasherPartitions.ItemsSource = null;
                GridUatFlasherPartitions.ItemsSource = filtered;
            }
        }

