        // --- Dump Workspace State & Handlers ---
        private readonly ObservableCollection<UatDumpRegionModel> _uatDumpRegions = new();

        private void InitializeUatDumpRegions()
        {
            _uatDumpRegions.Clear();
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 1, Name = "eMMC User Area (Main Storage)", StartLba = "0x00000000", EndLba = "0x03ABFFFF", Size = "64.0 GB (124,518,400 Sectors)", Offset = "0x00000000", Status = "ONLINE (Read/Write)" });
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 2, Name = "Boot 1 / boot0 (Hardware Boot Area 1)", StartLba = "0x00000000", EndLba = "0x00001FFF", Size = "4096 KB (4 MB)", Offset = "0x00000000", Status = "PROTECTED (ROM Code)" });
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 3, Name = "Boot 2 / boot1 (Hardware Boot Area 2)", StartLba = "0x00000000", EndLba = "0x00001FFF", Size = "4096 KB (4 MB)", Offset = "0x00000000", Status = "PROTECTED (Secondary Boot)" });
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 4, Name = "RPMB (Replay Protected Memory Block)", StartLba = "0x00000000", EndLba = "0x000003FF", Size = "512 KB (Authentication)", Offset = "0x00000000", Status = "HARDWARE KEY LOCKED" });
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 5, Name = "General Purpose Partition 1 (GPP1)", StartLba = "0x00000000", EndLba = "0x00007FFF", Size = "16 MB (Hardware Config)", Offset = "0x00000000", Status = "READY" });
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 6, Name = "General Purpose Partition 2 (GPP2)", StartLba = "0x00000000", EndLba = "0x00007FFF", Size = "16 MB (Modem NV Staging)", Offset = "0x00000000", Status = "READY" });
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 7, Name = "UFS LUN 0 (Main Userdata & System)", StartLba = "0x00000000", EndLba = "0x0757FFFF", Size = "128.0 GB (UFS 2.2 Turbo)", Offset = "0x00000000", Status = "ACTIVE LUN" });
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 8, Name = "UFS LUN 1 (Boot A Hardware Partition)", StartLba = "0x00000000", EndLba = "0x00003FFF", Size = "8192 KB (8 MB UFS A)", Offset = "0x00000000", Status = "ACTIVE BOOT" });
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 9, Name = "UFS LUN 2 (Boot B Hardware Partition)", StartLba = "0x00000000", EndLba = "0x00003FFF", Size = "8192 KB (8 MB UFS B)", Offset = "0x00000000", Status = "BACKUP BOOT" });
            _uatDumpRegions.Add(new UatDumpRegionModel { Index = 10, Name = "UFS LUN 3 (RPMB Replay Secure Storage)", StartLba = "0x00000000", EndLba = "0x000007FF", Size = "1024 KB (RPMB UFS)", Offset = "0x00000000", Status = "SECURE ENCLAVE" });
        }

        

